test("P98 WebRTC AEC3 nonlinear residual echo & render-to-capture delay drift guard suppresses false self-barge-in and permits genuine near-end double-talk", () => {
  // 1. Render-to-capture delay >250ms or unconverged AEC3 filter -> hold hair-trigger barge-in and re-estimate delay buffer
  const delayDrift = evaluateWebRtcAec3ResidualEchoFalseBargeInAndDelayDriftGuard({
    callId: "call-p98-drift-01",
    measuredErleDb: 16,
    renderToCaptureDelayMs: 310,
    uplinkDownlinkCrossCorrelation: 0.4,
    nearEndIndependentPitchDetected: false,
    aec3FilterConverged: false,
  });
  assert.equal(delayDrift.allowed, false);
  assert.equal(delayDrift.aec3EchoSuppressionHealthy, false);
  assert.equal(delayDrift.allowVadBargeInTrigger, false);
  assert.equal(
    delayDrift.actionCode,
    "REESTIMATE_AEC3_DELAY_AGNOSTIC_BUFFER_AND_HOLD_HAIR_TRIGGER_BARGE_IN"
  );
  assert.equal(
    delayDrift.reason,
    "WEBRTC_AEC3_RENDER_CAPTURE_DELAY_DRIFT_OR_UNCONVERGED_FILTER"
  );
  assert.equal(
    delayDrift.policyCode,
    "P98-WEBRTC-AEC3-NONLINEAR-RESIDUAL-ECHO-DOUBLE-TALK-FALSE-BARGE-IN-AND-DELAY-DRIFT-GUARD"
  );

  // 2. High cross-correlation (>=0.65), low ERLE (<12dB), and no independent near-end pitch -> suppress false self-barge-in
  const residualEcho = evaluateWebRtcAec3ResidualEchoFalseBargeInAndDelayDriftGuard({
    callId: "call-p98-echo-02",
    measuredErleDb: 7.5,
    renderToCaptureDelayMs: 65,
    uplinkDownlinkCrossCorrelation: 0.84,
    nearEndIndependentPitchDetected: false,
    aec3FilterConverged: true,
  });
  assert.equal(residualEcho.allowed, false);
  assert.equal(residualEcho.aec3EchoSuppressionHealthy, false);
  assert.equal(residualEcho.allowVadBargeInTrigger, false);
  assert.equal(
    residualEcho.actionCode,
    "SUPPRESS_FALSE_SELF_BARGE_IN_DROP_ECHOED_ASR_TOKENS_AND_ENGAGE_NONLINEAR_NLP"
  );
  assert.equal(
    residualEcho.reason,
    "WEBRTC_AEC3_NONLINEAR_RESIDUAL_ECHO_SELF_BARGE_IN_BLOCKED"
  );

  // 3. Converged AEC3 filter and genuine near-end speaker pitch detected -> permit genuine user barge-in
  const genuineDoubleTalk = evaluateWebRtcAec3ResidualEchoFalseBargeInAndDelayDriftGuard({
    callId: "call-p98-valid-03",
    measuredErleDb: 19.2,
    renderToCaptureDelayMs: 48,
    uplinkDownlinkCrossCorrelation: 0.22,
    nearEndIndependentPitchDetected: true,
    aec3FilterConverged: true,
  });
  assert.equal(genuineDoubleTalk.allowed, true);
  assert.equal(genuineDoubleTalk.aec3EchoSuppressionHealthy, true);
  assert.equal(genuineDoubleTalk.allowVadBargeInTrigger, true);
  assert.equal(
    genuineDoubleTalk.actionCode,
    "PERMIT_GENUINE_USER_BARGE_IN_AND_STREAM_CLEAN_UPLINK"
  );
  assert.equal(
    genuineDoubleTalk.reason,
    "WEBRTC_AEC3_ERLE_CONVERGED_AND_GENUINE_NEAR_END_DOUBLE_TALK_VERIFIED"
  );
});

