test("P102 real-time tool-call circuit breaker, P95 hedged read fallback & mutating idempotency-key guard short-circuits open breakers, blocks duplicate writes, and hedges slow reads", () => {
  // 1. Downstream microservice circuit breaker open or error rate >=50% -> fail fast in <15ms
  const breakerOpen = evaluateRealtimeToolCallCircuitBreakerHedgedReadAndIdempotencyGuard({
    callId: "call-p102-breaker-01",
    toolName: "lookup_policy_ledger",
    toolMutatesState: false,
    idempotencyKeyPresent: true,
    downstreamErrorRatePct: 68,
    circuitBreakerState: "OPEN",
    elapsedLatencyMs: 12,
    deadlineBudgetMs: 1800,
    hedgedReadTriggerMs: 600,
    hedgedReadReplicaDispatched: false,
    retryAttemptedOnTimeout: false,
  });
  assert.equal(breakerOpen.allowed, false);
  assert.equal(breakerOpen.toolResilienceAndIdempotencyVerified, false);
  assert.equal(breakerOpen.hedgedReadActivated, false);
  assert.equal(
    breakerOpen.actionCode,
    "SHORT_CIRCUIT_IN_15MS_SERVE_STALE_READ_CACHE_OR_ENQUEUE_DURABLE_ASYNC_CALLBACK"
  );
  assert.equal(
    breakerOpen.reason,
    "DOWNSTREAM_MICROSERVICE_CIRCUIT_BREAKER_OPEN_FAIL_FAST_ACTIVATED"
  );
  assert.equal(
    breakerOpen.policyCode,
    "P102-REALTIME-TOOL-CALL-CIRCUIT-BREAKER-HEDGED-FALLBACK-IDEMPOTENCY-KEY-AND-DEADLINE-PROPAGATION-GUARD"
  );

  // 2. Mutating write tool call retried after timeout (>1800ms) or missing Idempotency-Key -> block duplicate write retry
  const unsafeWriteRetry = evaluateRealtimeToolCallCircuitBreakerHedgedReadAndIdempotencyGuard({
    callId: "call-p102-write-02",
    toolName: "charge_card_installment",
    toolMutatesState: true,
    idempotencyKeyPresent: false,
    downstreamErrorRatePct: 10,
    circuitBreakerState: "CLOSED",
    elapsedLatencyMs: 2400,
    deadlineBudgetMs: 1800,
    hedgedReadTriggerMs: 600,
    hedgedReadReplicaDispatched: false,
    retryAttemptedOnTimeout: true,
  });
  assert.equal(unsafeWriteRetry.allowed, false);
  assert.equal(unsafeWriteRetry.toolResilienceAndIdempotencyVerified, false);
  assert.equal(
    unsafeWriteRetry.actionCode,
    "ABORT_DUPLICATE_WRITE_RETRY_PROPAGATE_GRPC_DEADLINE_AND_QUERY_RECONCILIATION_LEDGER"
  );
  assert.equal(
    unsafeWriteRetry.reason,
    "MUTATING_TOOL_CALL_MISSING_IDEMPOTENCY_KEY_OR_UNSAFE_TIMEOUT_RETRY_BLOCKED"
  );

  // 3. Read-only tool call exceeds P95 latency budget without hedged replica request -> dispatch hedged read & stream filler
  const unhedgedSlowRead = evaluateRealtimeToolCallCircuitBreakerHedgedReadAndIdempotencyGuard({
    callId: "call-p102-hedge-03",
    toolName: "get_order_tracking",
    toolMutatesState: false,
    idempotencyKeyPresent: true,
    downstreamErrorRatePct: 5,
    circuitBreakerState: "CLOSED",
    elapsedLatencyMs: 920,
    deadlineBudgetMs: 1800,
    hedgedReadTriggerMs: 600,
    hedgedReadReplicaDispatched: false,
    retryAttemptedOnTimeout: false,
  });
  assert.equal(unhedgedSlowRead.allowed, false);
  assert.equal(unhedgedSlowRead.toolResilienceAndIdempotencyVerified, false);
  assert.equal(unhedgedSlowRead.hedgedReadActivated, true);
  assert.equal(
    unhedgedSlowRead.actionCode,
    "DISPATCH_HEDGED_READ_TO_WARM_SECONDARY_REPLICA_AND_STREAM_LATENCY_MASKING_FILLER"
  );
  assert.equal(
    unhedgedSlowRead.reason,
    "READ_ONLY_TOOL_P95_TAIL_LATENCY_EXCEEDED_WITHOUT_HEDGED_REPLICA_REQUEST"
  );

  // 4. Healthy downstream circuit, valid Idempotency-Key, and bounded latency -> commit tool response
  const healthyToolCall = evaluateRealtimeToolCallCircuitBreakerHedgedReadAndIdempotencyGuard({
    callId: "call-p102-valid-04",
    toolName: "charge_card_installment",
    toolMutatesState: true,
    idempotencyKeyPresent: true,
    downstreamErrorRatePct: 2,
    circuitBreakerState: "CLOSED",
    elapsedLatencyMs: 380,
    deadlineBudgetMs: 1800,
    hedgedReadTriggerMs: 600,
    hedgedReadReplicaDispatched: false,
    retryAttemptedOnTimeout: false,
  });
  assert.equal(healthyToolCall.allowed, true);
  assert.equal(healthyToolCall.toolResilienceAndIdempotencyVerified, true);
  assert.equal(healthyToolCall.hedgedReadActivated, false);
  assert.equal(
    healthyToolCall.actionCode,
    "COMMIT_BOUNDED_LATENCY_TOOL_RESPONSE_TO_VOICE_TURN"
  );
  assert.equal(
    healthyToolCall.reason,
    "REALTIME_TOOL_DEADLINE_IDEMPOTENCY_AND_CIRCUIT_HEALTH_VERIFIED"
  );
});

