  assert.equal(healthyMedia.mediaPlaneLatchSecure, true);
  assert.equal(healthyMedia.portPoolHealthy, true);
  assert.equal(healthyMedia.rtcpMuxSinglePortActive, true);
  assert.equal(
    healthyMedia.actionCode,
    "PERMIT_AUTHENTICATED_SRTP_MEDIA_FLOW_WITH_SINGLE_PORT_RTCP_MUX"
  );
