test("P112 WebRTC RFC 7675 ICE consent freshness, zombie TURN allocation reaper & STUN flood guard halts SRTP on consent expiry, reaps orphaned TURN ports, and throttles STUN floods", () => {
  // 1. >= 6 unanswered STUN consent probes or >= 30,000ms without consent response -> revoke ICE consent and halt SRTP in 0ms
  const consentExpired = evaluateWebRtcIceConsentFreshnessAndZombieTurnReaperGuard({
    sessionId: "call-p112-consent-01",
    consecutiveUnansweredStunConsentProbes: 6,
    millisSinceLastConsentResponse: 31500,
    explicitIcmpUnreachableOrStunForbiddenReceived: false,
    turnAllocationActive: true,
    signalingConnected: true,
    rtpInboundSilenceMs: 4200,
    inboundStunBindingRequestsPerSec: 12,
    maxAllowedStunRequestsPerSec: 50,
  });
  assert.equal(consentExpired.allowed, false);
  assert.equal(consentExpired.iceConsentFresh, false);
  assert.equal(
    consentExpired.actionCode,
    "REVOKE_ICE_MEDIA_CONSENT_HALT_OUTBOUND_SRTP_AND_DISPATCH_TURN_REFRESH_LIFETIME_ZERO"
  );
  assert.equal(
    consentExpired.reason,
    "RFC7675_ICE_CONSENT_FRESHNESS_EXPIRED_OR_EXPLICIT_REVOCATION_HALTING_SRTP_TRANSMISSION"
  );
  assert.equal(
    consentExpired.policyCode,
    "P112-WEBRTC-RFC7675-ICE-CONSENT-FRESHNESS-ZOMBIE-TURN-REAPER-AND-STUN-FLOOD-GUARD"
  );

  // 2. TURN allocation remains active while signaling disconnected and inbound RTP silence >= 15,000ms -> reap zombie TURN allocation
  const zombieTurnReaped = evaluateWebRtcIceConsentFreshnessAndZombieTurnReaperGuard({
    sessionId: "call-p112-zombie-02",
    consecutiveUnansweredStunConsentProbes: 2,
    millisSinceLastConsentResponse: 11000,
    explicitIcmpUnreachableOrStunForbiddenReceived: false,
    turnAllocationActive: true,
    signalingConnected: false,
    rtpInboundSilenceMs: 18500,
    inboundStunBindingRequestsPerSec: 8,
    maxAllowedStunRequestsPerSec: 50,
  });
  assert.equal(zombieTurnReaped.allowed, false);
  assert.equal(zombieTurnReaped.turnAllocationHealthy, false);
  assert.equal(
    zombieTurnReaped.actionCode,
    "REAP_ZOMBIE_TURN_ALLOCATION_WITH_REFRESH_LIFETIME_ZERO_AND_RELEASE_RELAY_PORT"
  );
  assert.equal(
    zombieTurnReaped.reason,
    "ORPHANED_ZOMBIE_TURN_ALLOCATION_DETECTED_AFTER_SIGNALING_DISCONNECT_AND_RTP_SILENCE"
  );

  // 3. Inbound STUN Binding request rate (140/s) exceeds 50/s cap -> throttle flood
  const stunFloodThrottled = evaluateWebRtcIceConsentFreshnessAndZombieTurnReaperGuard({
    sessionId: "call-p112-flood-03",
    consecutiveUnansweredStunConsentProbes: 0,
    millisSinceLastConsentResponse: 3200,
    explicitIcmpUnreachableOrStunForbiddenReceived: false,
    turnAllocationActive: true,
    signalingConnected: true,
    rtpInboundSilenceMs: 200,
    inboundStunBindingRequestsPerSec: 140,
    maxAllowedStunRequestsPerSec: 50,
  });
  assert.equal(stunFloodThrottled.allowed, false);
  assert.equal(stunFloodThrottled.stunRateWithinLimit, false);
  assert.equal(
    stunFloodThrottled.actionCode,
    "THROTTLE_INBOUND_STUN_TRANSACTIONS_AND_DROP_EXCESS_BINDING_PROBES"
  );
  assert.equal(
    stunFloodThrottled.reason,
    "WEBRTC_STUN_BINDING_REQUEST_FLOOD_EXCEEDS_PER_CANDIDATE_RATE_LIMIT"
  );

  // 4. Fresh ICE consent, active signaling, and bounded STUN rate -> continue SRTP streaming
  const healthyConsent = evaluateWebRtcIceConsentFreshnessAndZombieTurnReaperGuard({
    sessionId: "call-p112-valid-04",
    consecutiveUnansweredStunConsentProbes: 0,
    millisSinceLastConsentResponse: 4100,
    explicitIcmpUnreachableOrStunForbiddenReceived: false,
    turnAllocationActive: true,
    signalingConnected: true,
    rtpInboundSilenceMs: 120,
    inboundStunBindingRequestsPerSec: 6,
    maxAllowedStunRequestsPerSec: 50,
  });
  assert.equal(healthyConsent.allowed, true);
  assert.equal(healthyConsent.iceConsentFresh, true);
  assert.equal(healthyConsent.turnAllocationHealthy, true);
  assert.equal(healthyConsent.stunRateWithinLimit, true);
  assert.equal(
    healthyConsent.actionCode,
    "CONTINUE_CONSENTED_SRTP_MEDIA_STREAMING"
  );
  assert.equal(
    healthyConsent.reason,
    "RFC7675_ICE_CONSENT_FRESH_TURN_LIFECYCLE_AND_STUN_RATE_HEALTHY"
  );
});

