test("P114 SIP RFC 3261 Max-Forwards / Via loop-spiral detection, parallel forking multiple-200-OK glare & Re-INVITE 491 backoff guard rejects routing loops, cleans secondary forked legs, and enforces RFC 3261 § 14.2 backoff", () => {
  // 1. Max-Forwards exhausted (<= 0) or circular Via/Diversion loop detected -> reject with SIP 482/483
  const loopDetected = evaluateSipRfc3261LoopSpiralAndForkingGlareGuard({
    callId: "call-p114-loop-01",
    maxForwardsHeaderValue: 0,
    viaBranchLoopOrCircularDiversionDetected: true,
    parallelForkedTwoHundredOkCount: 1,
    secondaryWinningLegAckAndByeWithRfc3326Dispatched: true,
    simultaneousReInviteGlare491Detected: false,
    rfc3261OwnerDeterministicBackoffTimerApplied: true,
  });
  assert.equal(loopDetected.allowed, false);
  assert.equal(loopDetected.loopFreeRouting, false);
  assert.equal(
    loopDetected.actionCode,
    "REJECT_WITH_SIP_482_LOOP_DETECTED_OR_483_TOO_MANY_HOPS_AND_HALT_DIVERSION"
  );
  assert.equal(
    loopDetected.reason,
    "SIP_RFC3261_MAX_FORWARDS_EXHAUSTED_OR_VIA_LOOP_SPIRAL_DETECTED"
  );
  assert.equal(
    loopDetected.policyCode,
    "P114-SIP-RFC3261-LOOP-MAX-FORWARDS-SPIRAL-DETECTION-AND-FORKING-GLARE-CANCEL-GUARD"
  );

  // 2. Parallel forking yields 2 simultaneous 200 OK responses without immediate ACK + BYE (RFC 3326) on secondary leg -> block orphan leg glare
  const forkingGlareBlocked = evaluateSipRfc3261LoopSpiralAndForkingGlareGuard({
    callId: "call-p114-fork-02",
    maxForwardsHeaderValue: 64,
    viaBranchLoopOrCircularDiversionDetected: false,
    parallelForkedTwoHundredOkCount: 2,
    secondaryWinningLegAckAndByeWithRfc3326Dispatched: false,
    simultaneousReInviteGlare491Detected: false,
    rfc3261OwnerDeterministicBackoffTimerApplied: true,
  });
  assert.equal(forkingGlareBlocked.allowed, false);
  assert.equal(forkingGlareBlocked.forkingLegClean, false);
  assert.equal(
    forkingGlareBlocked.actionCode,
    "DISPATCH_IMMEDIATE_ACK_AND_BYE_WITH_RFC3326_COMPLETED_ELSEWHERE_ON_SECONDARY_LEG"
  );
  assert.equal(
    forkingGlareBlocked.reason,
    "SIP_PARALLEL_FORKING_MULTIPLE_200_OK_ORPHAN_LEG_GLARE_DETECTED"
  );

  // 3. Simultaneous Re-INVITE glare (491 Request Pending) without RFC 3261 § 14.2 owner backoff timer -> enforce backoff
  const reinviteGlareBlocked = evaluateSipRfc3261LoopSpiralAndForkingGlareGuard({
    callId: "call-p114-491-03",
    maxForwardsHeaderValue: 64,
    viaBranchLoopOrCircularDiversionDetected: false,
    parallelForkedTwoHundredOkCount: 1,
    secondaryWinningLegAckAndByeWithRfc3326Dispatched: true,
    simultaneousReInviteGlare491Detected: true,
    rfc3261OwnerDeterministicBackoffTimerApplied: false,
  });
  assert.equal(reinviteGlareBlocked.allowed, false);
  assert.equal(reinviteGlareBlocked.reinviteGlareResolved, false);
  assert.equal(
    reinviteGlareBlocked.actionCode,
    "ENFORCE_RFC3261_SECTION_14_2_CALLID_OWNER_JITTER_BACKOFF_TIMER"
  );
  assert.equal(
    reinviteGlareBlocked.reason,
    "SIP_RFC3261_491_REINVITE_GLARE_MISSING_DETERMINISTIC_JITTER_BACKOFF"
  );

  // 4. Healthy SIP routing hops, clean single dialog leg, and resolved Re-INVITE state -> allow
  const healthySip = evaluateSipRfc3261LoopSpiralAndForkingGlareGuard({
    callId: "call-p114-valid-04",
    maxForwardsHeaderValue: 68,
    viaBranchLoopOrCircularDiversionDetected: false,
    parallelForkedTwoHundredOkCount: 1,
    secondaryWinningLegAckAndByeWithRfc3326Dispatched: true,
    simultaneousReInviteGlare491Detected: false,
    rfc3261OwnerDeterministicBackoffTimerApplied: true,
  });
  assert.equal(healthySip.allowed, true);
  assert.equal(healthySip.loopFreeRouting, true);
  assert.equal(healthySip.forkingLegClean, true);
  assert.equal(healthySip.reinviteGlareResolved, true);
  assert.equal(
    healthySip.actionCode,
    "CONTINUE_SIP_DIALOG_SIGNALING"
  );
  assert.equal(
    healthySip.reason,
    "SIP_RFC3261_ROUTING_HOPS_PARALLEL_FORKING_AND_REINVITE_STATE_HEALTHY"
  );
});

