test("P118 RTP RFC 3550 § 8.2 SSRC collision/loop resolution & RFC 5285 header extension / IPv6 Path MTU guard dispatches RTCP BYE on SSRC collisions, upgrades >16B metadata to 0x1000 2-byte header extension, and prevents MTU fragmentation", () => {
  // 1. SSRC collision across source transports without RTCP BYE + CSPRNG SSRC reallocation -> dispatch RTCP BYE and quarantine loop
  const ssrcCollisionBlocked = evaluateRtpRfc3550SsrcCollisionLoopAndRfc5285HeaderExtensionGuard({
    sessionId: "rtp-p118-ssrc-01",
    ssrcCollisionOrLoopDetectedAcrossSourceTransports: true,
    rtcpByeDispatchedAndNewRandomSsrcAllocated: false,
    sameSourceTransportLoopPersistsAfterRekey: false,
    oneByteHeaderExtensionElementPayloadBytes: 8,
    twoByteHeaderExtensionProfile0x1000Negotiated: false,
    totalRtpPacketSizeBytes: 240,
    pathMtuPayloadLimitBytes: 1200,
  });
  assert.equal(ssrcCollisionBlocked.allowed, false);
  assert.equal(ssrcCollisionBlocked.ssrcNamespaceConflictFree, false);
  assert.equal(
    ssrcCollisionBlocked.policyCode,
    "P118-RTP-RFC3550-SSRC-COLLISION-LOOP-RESOLUTION-AND-RFC5285-TWOBYTE-HEADER-EXTENSION-CSRC-OVERFLOW-GUARD"
  );
  assert.equal(
    ssrcCollisionBlocked.actionCode,
    "DISPATCH_RTCP_BYE_ALLOCATE_NEW_CSPRNG_SSRC_AND_QUARANTINE_LOOPED_TRANSPORT"
  );
  assert.equal(
    ssrcCollisionBlocked.reason,
    "RFC3550_SECTION_8_2_SSRC_COLLISION_OR_MEDIA_LOOP_UNRESOLVED_WITHOUT_RTCP_BYE_AND_REALLOCATION"
  );

  // 2. Header extension payload (28B > 16B) packed into RFC 5285 1-byte 0xBEDE profile without 2-byte 0x1000 profile -> upgrade to 0x1000
  const headerOverflowBlocked = evaluateRtpRfc3550SsrcCollisionLoopAndRfc5285HeaderExtensionGuard({
    sessionId: "rtp-p118-ext-02",
    ssrcCollisionOrLoopDetectedAcrossSourceTransports: false,
    rtcpByeDispatchedAndNewRandomSsrcAllocated: true,
    sameSourceTransportLoopPersistsAfterRekey: false,
    oneByteHeaderExtensionElementPayloadBytes: 28,
    twoByteHeaderExtensionProfile0x1000Negotiated: false,
    totalRtpPacketSizeBytes: 320,
    pathMtuPayloadLimitBytes: 1200,
  });
  assert.equal(headerOverflowBlocked.allowed, false);
  assert.equal(headerOverflowBlocked.headerExtensionBoundsValid, false);
  assert.equal(
    headerOverflowBlocked.actionCode,
    "UPGRADE_RTP_HEADER_EXTENSION_TO_RFC5285_TWO_BYTE_0X1000_PROFILE_OR_STRIP_OVERLONG_METADATA"
  );
  assert.equal(
    headerOverflowBlocked.reason,
    "RFC5285_ONE_BYTE_RTP_HEADER_EXTENSION_0XBEDE_EXCEEDS_16BYTE_ELEMENT_LIMIT"
  );

  // 3. Total RTP packet size (1,340B) exceeds IPv6 Path MTU limit (1,200B) -> clamp CSRC list and fragment large metadata out of band
  const mtuExceededBlocked = evaluateRtpRfc3550SsrcCollisionLoopAndRfc5285HeaderExtensionGuard({
    sessionId: "rtp-p118-mtu-03",
    ssrcCollisionOrLoopDetectedAcrossSourceTransports: false,
    rtcpByeDispatchedAndNewRandomSsrcAllocated: true,
    sameSourceTransportLoopPersistsAfterRekey: false,
    oneByteHeaderExtensionElementPayloadBytes: 28,
    twoByteHeaderExtensionProfile0x1000Negotiated: true,
    totalRtpPacketSizeBytes: 1340,
    pathMtuPayloadLimitBytes: 1200,
  });
  assert.equal(mtuExceededBlocked.allowed, false);
  assert.equal(mtuExceededBlocked.mtuSafetyGuaranteed, false);
  assert.equal(
    mtuExceededBlocked.actionCode,
    "CLAMP_CSRC_LIST_AND_FRAGMENT_LARGE_METADATA_OUT_OF_BAND_TO_PREVENT_UDP_DROP"
  );
  assert.equal(
    mtuExceededBlocked.reason,
    "RTP_PACKET_WITH_CSRC_AND_HEADER_EXTENSIONS_EXCEEDS_IPV6_PATH_MTU_FRAGMENTATION_THRESHOLD"
  );

  // 4. Clean SSRC namespace, negotiated 0x1000 2-byte header extension, and RTP packet within Path MTU -> allow
  const healthyRtpFrame = evaluateRtpRfc3550SsrcCollisionLoopAndRfc5285HeaderExtensionGuard({
    sessionId: "rtp-p118-valid-04",
    ssrcCollisionOrLoopDetectedAcrossSourceTransports: true,
    rtcpByeDispatchedAndNewRandomSsrcAllocated: true,
    sameSourceTransportLoopPersistsAfterRekey: false,
    oneByteHeaderExtensionElementPayloadBytes: 28,
    twoByteHeaderExtensionProfile0x1000Negotiated: true,
    totalRtpPacketSizeBytes: 420,
    pathMtuPayloadLimitBytes: 1200,
  });
  assert.equal(healthyRtpFrame.allowed, true);
  assert.equal(healthyRtpFrame.ssrcNamespaceConflictFree, true);
  assert.equal(healthyRtpFrame.headerExtensionBoundsValid, true);
  assert.equal(healthyRtpFrame.mtuSafetyGuaranteed, true);
  assert.equal(
    healthyRtpFrame.actionCode,
    "FORWARD_RTP_MEDIA_FRAME"
  );
  assert.equal(
    healthyRtpFrame.reason,
    "RFC3550_SSRC_NAMESPACE_AND_RFC5285_HEADER_EXTENSION_MTU_HEALTHY"
  );
});

