test("P122 WebRTC RFC 8627 FlexFEC / Opus LBRR redundancy overhead congestion-spiral & 2D burst-loss recovery guard sheds out-of-band FlexFEC on narrowband links and activates 2D parity on wideband bursts", () => {
  // 1. Source audio (32 kbps) + FlexFEC redundancy (24 kbps) = 56 kbps exceeds 90% of TWCC available uplink (22 kbps) -> shed out-of-band FlexFEC and downshift Opus to 12 kbps SILK
  const congestionSpiralBlocked = evaluateWebrtcRfc8627FlexfecOpusLbrrCongestionSpiralGuard({
    sessionId: "webrtc-p122-spiral-01",
    twccAvailableUplinkKbps: 22,
    sourceAudioBitrateKbps: 32,
    fecRedundancyBitrateKbps: 24,
    observedPacketLossRatePct: 14,
    consecutiveBurstLossFrames: 4,
    opusInBandLbrrEnabled: true,
    rfc8627Flexfec2dMatrixActive: true,
  });
  assert.equal(congestionSpiralBlocked.allowed, false);
  assert.equal(congestionSpiralBlocked.congestionSpiralAvoided, false);
  assert.equal(congestionSpiralBlocked.redundancyBudgetCompliant, false);
  assert.equal(
    congestionSpiralBlocked.policyCode,
    "P122-WEBRTC-RFC8627-FLEXFEC-OPUS-LBRR-REDUNDANCY-OVERHEAD-CONGESTION-SPIRAL-AND-BURST-RECOVERY-GUARD"
  );
  assert.equal(
    congestionSpiralBlocked.actionCode,
    "SHED_OUT_OF_BAND_FLEXFEC_DOWNSHIFT_OPUS_TO_12KBPS_SILK_AND_KEEP_LIGHTWEIGHT_LBRR_ONLY"
  );
  assert.equal(
    congestionSpiralBlocked.reason,
    "RFC8627_FEC_REDUNDANCY_EXCEEDS_TWCC_LINK_HEADROOM_SELF_INFLICTED_CONGESTION_SPIRAL_BLOCKED"
  );

  // 2. Ample TWCC uplink headroom (120 kbps >= 64 kbps) with 12% burst loss (4 consecutive frames) but Opus LBRR or 2D FlexFEC disabled -> activate LBRR + 2D FlexFEC parity
  const burstParityMissing = evaluateWebrtcRfc8627FlexfecOpusLbrrCongestionSpiralGuard({
    sessionId: "webrtc-p122-burst-02",
    twccAvailableUplinkKbps: 120,
    sourceAudioBitrateKbps: 32,
    fecRedundancyBitrateKbps: 12,
    observedPacketLossRatePct: 12,
    consecutiveBurstLossFrames: 4,
    opusInBandLbrrEnabled: false,
    rfc8627Flexfec2dMatrixActive: false,
  });
  assert.equal(burstParityMissing.allowed, false);
  assert.equal(burstParityMissing.burstFecCoverageAdequate, false);
  assert.equal(
    burstParityMissing.actionCode,
    "ACTIVATE_OPUS_INBAND_LBRR_AND_RFC8627_2D_INTERLEAVED_FLEXFEC_PARITY"
  );
  assert.equal(
    burstParityMissing.reason,
    "HIGH_BURST_PACKET_LOSS_WITH_HEADROOM_MISSING_OPUS_LBRR_OR_2D_FLEXFEC_PARITY"
  );

  // 3. FEC redundancy bitrate (48 kbps) exceeds 1.0x source audio bitrate (32 kbps) -> clamp FEC overhead ratio
  const excessiveFecRatioBlocked = evaluateWebrtcRfc8627FlexfecOpusLbrrCongestionSpiralGuard({
    sessionId: "webrtc-p122-ratio-03",
    twccAvailableUplinkKbps: 180,
    sourceAudioBitrateKbps: 32,
    fecRedundancyBitrateKbps: 48,
    observedPacketLossRatePct: 4,
    consecutiveBurstLossFrames: 1,
    opusInBandLbrrEnabled: true,
    rfc8627Flexfec2dMatrixActive: true,
  });
  assert.equal(excessiveFecRatioBlocked.allowed, false);
  assert.equal(excessiveFecRatioBlocked.redundancyBudgetCompliant, false);
  assert.equal(
    excessiveFecRatioBlocked.actionCode,
    "CAP_FEC_PARITY_BITRATE_TO_100PCT_OF_SOURCE_OPUS_PAYLOAD"
  );
  assert.equal(
    excessiveFecRatioBlocked.reason,
    "FEC_REDUNDANCY_RATIO_EXCEEDS_MAXIMUM_AUDIO_OVERHEAD_CEILING"
  );

  // 4. Healthy TWCC headroom, bounded FEC overhead, and active Opus LBRR + 2D FlexFEC under burst loss -> allow
  const healthyFlexfecStream = evaluateWebrtcRfc8627FlexfecOpusLbrrCongestionSpiralGuard({
    sessionId: "webrtc-p122-valid-04",
    twccAvailableUplinkKbps: 128,
    sourceAudioBitrateKbps: 32,
    fecRedundancyBitrateKbps: 16,
    observedPacketLossRatePct: 10,
    consecutiveBurstLossFrames: 3,
    opusInBandLbrrEnabled: true,
    rfc8627Flexfec2dMatrixActive: true,
  });
  assert.equal(healthyFlexfecStream.allowed, true);
  assert.equal(healthyFlexfecStream.congestionSpiralAvoided, true);
  assert.equal(healthyFlexfecStream.burstFecCoverageAdequate, true);
  assert.equal(healthyFlexfecStream.redundancyBudgetCompliant, true);
  assert.equal(
    healthyFlexfecStream.actionCode,
    "TRANSMIT_RATE_ADAPTED_OPUS_AND_FLEXFEC_STREAM"
  );
  assert.equal(
    healthyFlexfecStream.reason,
    "WEBRTC_RFC8627_FLEXFEC_AND_OPUS_LBRR_BITRATE_ALLOCATION_HEALTHY"
  );
});

