test("P124 SIP RFC 3262 PRACK 100rel retransmission flood, RFC 3312 QoS precondition gate & RFC 6141 rejected Re-INVITE/UPDATE atomic media rollback guard halts 183 retransmission storms, holds early TTS until dedicated bearer QoS is confirmed, and atomically rolls back rejected SDP offers", () => {
  // 1. Require: 100rel negotiated but matching RAck PRACK not sent within T1 or unacknowledged 183 retransmit count (6 > 4) -> dispatch PRACK and halt provisional retransmission storm
  const prackFloodBlocked = evaluateSipRfc3262Prack100relAndRfc3312QosPreconditionGuard({
    sessionId: "sip-p124-prack-01",
    require100relNegotiated: true,
    matchingRackPrackSentWithinT1: false,
    unacknowledged100relRetransmitCount: 6,
    rfc3312QosPreconditionMandatory: true,
    dedicatedBearerQosUpdateConfirmedBeforePromptPlay: true,
    midCallReInviteOrUpdateRejected: false,
    atomicRollbackToPreOfferSdpStateCompleted: true,
  });
  assert.equal(prackFloodBlocked.allowed, false);
  assert.equal(prackFloodBlocked.prack100relTransactionHealthy, false);
  assert.equal(
    prackFloodBlocked.policyCode,
    "P124-SIP-RFC3262-PRACK-100REL-RETRANSMISSION-FLOOD-RFC3312-QOS-PRECONDITION-AND-RFC6141-ROLLBACK-GUARD"
  );
  assert.equal(
    prackFloodBlocked.actionCode,
    "TRANSMIT_IMMEDIATE_PRACK_WITH_EXACT_RACK_RSEQ_CSEQ_HEADER_OR_ABORT_STALE_100REL_DIALOG"
  );
  assert.equal(
    prackFloodBlocked.reason,
    "RFC3262_100REL_UNACKNOWLEDGED_PROVISIONAL_RETRANSMISSION_FLOOD_OR_MISSING_RACK_PRACK"
  );

  // 2. Mandatory RFC 3312 QoS precondition active (`a=curr:qos local none`, `a=des:qos mandatory local sendrecv`) but agent attempts early media TTS before UPDATE confirms dedicated QCI-1 bearer -> hold opening TTS prompt
  const qosPreconditionBlocked = evaluateSipRfc3262Prack100relAndRfc3312QosPreconditionGuard({
    sessionId: "sip-p124-qos-02",
    require100relNegotiated: true,
    matchingRackPrackSentWithinT1: true,
    unacknowledged100relRetransmitCount: 0,
    rfc3312QosPreconditionMandatory: true,
    dedicatedBearerQosUpdateConfirmedBeforePromptPlay: false,
    midCallReInviteOrUpdateRejected: false,
    atomicRollbackToPreOfferSdpStateCompleted: true,
  });
  assert.equal(qosPreconditionBlocked.allowed, false);
  assert.equal(qosPreconditionBlocked.rfc3312QosPreconditionSatisfied, false);
  assert.equal(
    qosPreconditionBlocked.actionCode,
    "HOLD_TTS_GREETING_BUFFER_UNTIL_RFC3312_MANDATORY_QOS_SENDRECV_UPDATE_200OK_CONFIRMED"
  );
  assert.equal(
    qosPreconditionBlocked.reason,
    "RFC3312_QOS_PRECONDITION_BYPASSED_EARLY_MEDIA_PROMPT_PLAYED_BEFORE_DEDICATED_BEARER_UPDATE"
  );

  // 3. Mid-call Re-INVITE or UPDATE rejected (`488 Not Acceptable Here` / `491 Request Pending`) without atomic rollback to pre-offer SDP codec/PT/SRTP state -> atomically roll back media state
  const rfc6141RollbackMissingBlocked = evaluateSipRfc3262Prack100relAndRfc3312QosPreconditionGuard({
    sessionId: "sip-p124-rollback-03",
    require100relNegotiated: true,
    matchingRackPrackSentWithinT1: true,
    unacknowledged100relRetransmitCount: 0,
    rfc3312QosPreconditionMandatory: true,
    dedicatedBearerQosUpdateConfirmedBeforePromptPlay: true,
    midCallReInviteOrUpdateRejected: true,
    atomicRollbackToPreOfferSdpStateCompleted: false,
  });
  assert.equal(rfc6141RollbackMissingBlocked.allowed, false);
  assert.equal(rfc6141RollbackMissingBlocked.rfc6141OfferAnswerRollbackClean, false);
  assert.equal(
    rfc6141RollbackMissingBlocked.actionCode,
    "RESTORE_PRE_OFFER_NEGOTIATED_SDP_CODEC_AND_DIRECTIONALITY_STATE_PER_RFC6141"
  );
  assert.equal(
    rfc6141RollbackMissingBlocked.reason,
    "RFC6141_REJECTED_REINVITE_OR_UPDATE_MISSING_ATOMIC_PRE_OFFER_SDP_MEDIA_ROLLBACK"
  );

  // 4. Healthy RFC 3262 PRACK / 100rel handshake, confirmed RFC 3312 QoS precondition, and clean RFC 6141 SDP state -> allow
  const healthySipPrackSession = evaluateSipRfc3262Prack100relAndRfc3312QosPreconditionGuard({
    sessionId: "sip-p124-valid-04",
    require100relNegotiated: true,
    matchingRackPrackSentWithinT1: true,
    unacknowledged100relRetransmitCount: 0,
    rfc3312QosPreconditionMandatory: true,
    dedicatedBearerQosUpdateConfirmedBeforePromptPlay: true,
    midCallReInviteOrUpdateRejected: true,
    atomicRollbackToPreOfferSdpStateCompleted: true,
  });
  assert.equal(healthySipPrackSession.allowed, true);
  assert.equal(healthySipPrackSession.prack100relTransactionHealthy, true);
  assert.equal(healthySipPrackSession.rfc3312QosPreconditionSatisfied, true);
  assert.equal(healthySipPrackSession.rfc6141OfferAnswerRollbackClean, true);
  assert.equal(
    healthySipPrackSession.actionCode,
    "COMMIT_RELIABLE_PROVISIONAL_QOS_AND_OFFER_ANSWER_STATE"
  );
  assert.equal(
    healthySipPrackSession.reason,
    "SIP_RFC3262_PRACK_RFC3312_QOS_AND_RFC6141_SDP_STATE_HEALTHY"
  );
});

