test("P132 WebRTC/RTP RFC 6904 encrypted SRTP header extensions, RFC 6464 ssrc-audio-level VAD side-channel leak & RFC 5285/RFC 8285 extmap collision guard enforces header encryption, extmap-allow-mixed, and auth tag integrity", () => {
  // 1. Sensitive ssrc-audio-level or metadata extension sent in cleartext without RFC 6904 encryption -> block side-channel leak
  const cleartextAudioLevelBlocked = evaluateWebrtcRtpRfc6904EncryptedHeaderExtensionAndVadLeakGuard({
    sessionId: "webrtc-p132-cleartext-01",
    containsSensitiveAudioLevelOrMetadataExtension: true,
    rfc6904EncryptedHeaderExtensionActive: false,
    duplicateOrReservedExtmapIdDetected: false,
    extmapAllowMixedNegotiatedForTwoByteIds: true,
    rfc6904HeaderExtensionAuthTagAndMaskValid: true,
  });
  assert.equal(cleartextAudioLevelBlocked.allowed, false);
  assert.equal(cleartextAudioLevelBlocked.rfc6904HeaderExtensionEncrypted, false);
  assert.equal(
    cleartextAudioLevelBlocked.actionCode,
    "ENFORCE_RFC6904_SRTP_ENCRYPTED_HEADER_EXTENSION_OR_STRIP_VAD_AUDIO_LEVEL_TAG"
  );
  assert.equal(
    cleartextAudioLevelBlocked.reason,
    "RFC6904_CLEARTEXT_RTP_HEADER_EXTENSION_VAD_AUDIO_LEVEL_SIDE_CHANNEL_LEAK_BLOCKED"
  );

  // 2. Duplicate/reserved SDP extmap ID or two-byte extension ID (16-255) without a=extmap-allow-mixed -> reject
  const extmapCollisionBlocked = evaluateWebrtcRtpRfc6904EncryptedHeaderExtensionAndVadLeakGuard({
    sessionId: "webrtc-p132-extmap-02",
    containsSensitiveAudioLevelOrMetadataExtension: true,
    rfc6904EncryptedHeaderExtensionActive: true,
    duplicateOrReservedExtmapIdDetected: true,
    extmapAllowMixedNegotiatedForTwoByteIds: false,
    rfc6904HeaderExtensionAuthTagAndMaskValid: true,
  });
  assert.equal(extmapCollisionBlocked.allowed, false);
  assert.equal(extmapCollisionBlocked.rfc8285ExtmapIdsCollisionFree, false);
  assert.equal(
    extmapCollisionBlocked.actionCode,
    "REJECT_COLLIDING_SDP_EXTMAP_ID_AND_NORMALIZE_RFC8285_MIXED_ONE_TWO_BYTE_HEADER"
  );
  assert.equal(
    extmapCollisionBlocked.reason,
    "RFC5285_RFC8285_EXTMAP_ID_COLLISION_OR_MISSING_EXTMAP_ALLOW_MIXED_NEGOTIATION_BLOCKED"
  );

  // 3. RFC 6904 SRTP header extension keystream mask or authentication tag tampered -> drop packet
  const tamperedHeaderExtBlocked = evaluateWebrtcRtpRfc6904EncryptedHeaderExtensionAndVadLeakGuard({
    sessionId: "webrtc-p132-tamper-03",
    containsSensitiveAudioLevelOrMetadataExtension: true,
    rfc6904EncryptedHeaderExtensionActive: true,
    duplicateOrReservedExtmapIdDetected: false,
    extmapAllowMixedNegotiatedForTwoByteIds: true,
    rfc6904HeaderExtensionAuthTagAndMaskValid: false,
  });
  assert.equal(tamperedHeaderExtBlocked.allowed, false);
  assert.equal(tamperedHeaderExtBlocked.rfc6904AuthTagAndMaskIntegrityValid, false);
  assert.equal(
    tamperedHeaderExtBlocked.actionCode,
    "DROP_TAMPERED_RFC6904_RTP_HEADER_EXTENSION_PACKET_AND_ALERT_SRTP_INTEGRITY_MONITOR"
  );
  assert.equal(
    tamperedHeaderExtBlocked.reason,
    "RFC6904_SRTP_HEADER_EXTENSION_CIPHERTEXT_MASK_OR_AUTH_TAG_TAMPER_DETECTED"
  );

  // 4. Healthy RFC 6904 encrypted RTP header extension with collision-free RFC 8285 extmap and valid SRTP auth tag -> allow
  const healthyRfc6904Stream = evaluateWebrtcRtpRfc6904EncryptedHeaderExtensionAndVadLeakGuard({
    sessionId: "webrtc-p132-valid-04",
    containsSensitiveAudioLevelOrMetadataExtension: true,
    rfc6904EncryptedHeaderExtensionActive: true,
    duplicateOrReservedExtmapIdDetected: false,
    extmapAllowMixedNegotiatedForTwoByteIds: true,
    rfc6904HeaderExtensionAuthTagAndMaskValid: true,
  });
  assert.equal(healthyRfc6904Stream.allowed, true);
  assert.equal(healthyRfc6904Stream.rfc6904HeaderExtensionEncrypted, true);
  assert.equal(healthyRfc6904Stream.rfc8285ExtmapIdsCollisionFree, true);
  assert.equal(healthyRfc6904Stream.rfc6904AuthTagAndMaskIntegrityValid, true);
  assert.equal(
    healthyRfc6904Stream.actionCode,
    "ALLOW_VERIFIED_RFC6904_ENCRYPTED_RTP_HEADER_EXTENSION_STREAM"
  );
  assert.equal(
    healthyRfc6904Stream.reason,
    "WEBRTC_RTP_RFC6904_ENCRYPTED_HEADER_EXTENSION_AND_RFC8285_EXTMAP_HEALTHY"
  );
});

