test("P134 WebRTC/RTP RFC 8888 RTCP CCFB metric-block overflow, ATO (0x1FFF) desync & RFC 6679 ECN-CE spoofing guard drops overflowing CCFB packets, discards corrupted ATO delay samples, and ignores unnegotiated/spoofed ECN-CE congestion collapse", () => {
  // 1. num_reports metric block exceeds RTCP packet bounds or sequence span > 16,384 -> drop overflowing CCFB packet
  const ccfbBoundsOverflowBlocked = evaluateWebrtcRtpRfc8888RtcpCcfbFeedbackAndEcnGuard({
    sessionId: "webrtc-p134-bounds-01",
    declaredNumReportsCount: 24000,
    requiredMetricBlockBytes: 48000,
    remainingRtcpPacketBytes: 1200,
    maxAllowedReportsPerInterval: 16384,
    lostPacketWithNonSentinelAtoOrReceivedWith0x1fffDetected: false,
    reportTimestampWallclockSkewMs: 12,
    unnegotiatedEcnMarkingsOrSpoofedEcnCeStormDetected: false,
  });
  assert.equal(ccfbBoundsOverflowBlocked.allowed, false);
  assert.equal(ccfbBoundsOverflowBlocked.ccfbMetricBlockBoundsValid, false);
  assert.equal(
    ccfbBoundsOverflowBlocked.policyCode,
    "P134-WEBRTC-RTP-RFC8888-RTCP-CCFB-CONGESTION-CONTROL-FEEDBACK-REPORT-METRIC-BLOCK-OVERFLOW-ECN-CE-DESYNC-AND-ARRIVAL-TIME-OFFSET-WRAP-GUARD"
  );
  assert.equal(
    ccfbBoundsOverflowBlocked.actionCode,
    "DROP_OVERFLOWING_RFC8888_CCFB_PACKET_AND_CAP_PER_SSRC_METRIC_REPORT_WINDOW"
  );
  assert.equal(
    ccfbBoundsOverflowBlocked.reason,
    "RFC8888_RTCP_CCFB_NUM_REPORTS_METRIC_BLOCK_PACKET_BOUNDS_OR_INTERVAL_OVERFLOW_BLOCKED"
  );

  // 2. ATO 0x1FFF sentinel parsed as 8-second queuing delay or Report Timestamp skew -> discard corrupted ATO sample
  const atoSentinelDesyncBlocked = evaluateWebrtcRtpRfc8888RtcpCcfbFeedbackAndEcnGuard({
    sessionId: "webrtc-p134-ato-02",
    declaredNumReportsCount: 64,
    requiredMetricBlockBytes: 128,
    remainingRtcpPacketBytes: 512,
    maxAllowedReportsPerInterval: 16384,
    lostPacketWithNonSentinelAtoOrReceivedWith0x1fffDetected: true,
    reportTimestampWallclockSkewMs: 1450,
    unnegotiatedEcnMarkingsOrSpoofedEcnCeStormDetected: false,
  });
  assert.equal(atoSentinelDesyncBlocked.allowed, false);
  assert.equal(atoSentinelDesyncBlocked.atoSentinelAndReportTimestampConsistent, false);
  assert.equal(
    atoSentinelDesyncBlocked.actionCode,
    "DISCARD_CORRUPTED_ATO_DELAY_SAMPLE_AND_REANCHOR_RFC8888_1024HZ_REPORT_CLOCK"
  );
  assert.equal(
    atoSentinelDesyncBlocked.reason,
    "RFC8888_RTCP_CCFB_ATO_SENTINEL_0X1FFF_DESYNC_OR_REPORT_TIMESTAMP_SKEW_INJECTION_BLOCKED"
  );

  // 3. Unnegotiated ECN or 100% spoofed ECN-CE storm with flat queuing delay -> ignore ECN-CE bits and hold 24 kbps voice floor
  const spoofedEcnCeBlocked = evaluateWebrtcRtpRfc8888RtcpCcfbFeedbackAndEcnGuard({
    sessionId: "webrtc-p134-ecn-03",
    declaredNumReportsCount: 64,
    requiredMetricBlockBytes: 128,
    remainingRtcpPacketBytes: 512,
    maxAllowedReportsPerInterval: 16384,
    lostPacketWithNonSentinelAtoOrReceivedWith0x1fffDetected: false,
    reportTimestampWallclockSkewMs: 15,
    unnegotiatedEcnMarkingsOrSpoofedEcnCeStormDetected: true,
  });
  assert.equal(spoofedEcnCeBlocked.allowed, false);
  assert.equal(spoofedEcnCeBlocked.ecnMarkingAuthenticityVerified, false);
  assert.equal(
    spoofedEcnCeBlocked.actionCode,
    "IGNORE_UNAUTHENTICATED_ECN_CE_BITS_AND_HOLD_MIN_24KBPS_VOICE_BITRATE_FLOOR"
  );
  assert.equal(
    spoofedEcnCeBlocked.reason,
    "RFC6679_RFC8888_UNNEGOTIATED_ECN_OR_SPOOFED_ECN_CE_CONGESTION_COLLAPSE_STORM_BLOCKED"
  );

  // 4. Healthy RFC 8888 RTCP CCFB report with valid metric bounds, 1024Hz ATO clock, and authentic ECN-CE -> allow
  const healthyCcfbFeedback = evaluateWebrtcRtpRfc8888RtcpCcfbFeedbackAndEcnGuard({
    sessionId: "webrtc-p134-valid-04",
    declaredNumReportsCount: 64,
    requiredMetricBlockBytes: 128,
    remainingRtcpPacketBytes: 512,
    maxAllowedReportsPerInterval: 16384,
    lostPacketWithNonSentinelAtoOrReceivedWith0x1fffDetected: false,
    reportTimestampWallclockSkewMs: 18,
    unnegotiatedEcnMarkingsOrSpoofedEcnCeStormDetected: false,
  });
  assert.equal(healthyCcfbFeedback.allowed, true);
  assert.equal(healthyCcfbFeedback.ccfbMetricBlockBoundsValid, true);
  assert.equal(healthyCcfbFeedback.atoSentinelAndReportTimestampConsistent, true);
  assert.equal(healthyCcfbFeedback.ecnMarkingAuthenticityVerified, true);
  assert.equal(
    healthyCcfbFeedback.actionCode,
    "ALLOW_VERIFIED_RFC8888_CCFB_CONGESTION_CONTROL_UPDATE"
  );
  assert.equal(
    healthyCcfbFeedback.reason,
    "WEBRTC_RTP_RFC8888_RTCP_CCFB_AND_RFC6679_ECN_FEEDBACK_HEALTHY"
  );
});

