test("P136 SIP RFC 3261 / RFC 8760 Digest Auth MD5 / qop-less downgrade, stale nonce / nc replay, low-entropy cnonce & credential-stuffing guard rejects MD5/qop-less downgrades, blocks nc replays, and quarantines credential-stuffing floods", () => {
  // 1. Legacy MD5 or missing qop=auth-int or SDP body hash mismatch -> reject downgrade & body tamper
  const md5OrQopDowngradeBlocked = evaluateSipRfc3261DigestAuthNonceReplayAndQopDowngradeGuard({
    sessionId: "sip-p136-downgrade-01",
    digestAlgorithmSha256AndQopAuthIntEnforced: false,
    sdpBodyHashMatchesAuthIntEntityBody: false,
    nonceFreshAndNonceCountStrictlyMonotonic: true,
    cnonceEntropyBitsSufficient: true,
    failedAuthAttemptsInWindow: 1,
    maxAllowedFailedAuthAttempts: 5,
  });
  assert.equal(md5OrQopDowngradeBlocked.allowed, false);
  assert.equal(md5OrQopDowngradeBlocked.rfc8760Sha256AndQopAuthIntValid, false);
  assert.equal(
    md5OrQopDowngradeBlocked.policyCode,
    "P136-SIP-RFC3261-RFC8760-DIGEST-AUTH-MD5-DOWNGRADE-STALE-NONCE-NC-REPLAY-CNONCE-ENTROPY-AND-CREDENTIAL-STUFFING-GUARD"
  );
  assert.equal(
    md5OrQopDowngradeBlocked.actionCode,
    "REJECT_SIP_DIGEST_DOWNGRADE_ENFORCE_RFC8760_SHA256_AND_QOP_AUTH_INT"
  );
  assert.equal(
    md5OrQopDowngradeBlocked.reason,
    "RFC3261_RFC8760_SIP_DIGEST_MD5_OR_QOPLESS_DOWNGRADE_AND_SDP_BODY_TAMPER_BLOCKED"
  );

  // 2. Replayed nc=00000001 or expired nonce or low-entropy cnonce (<64 bits) -> drop replayed Authorization and challenge with fresh nonce
  const nonceCountReplayBlocked = evaluateSipRfc3261DigestAuthNonceReplayAndQopDowngradeGuard({
    sessionId: "sip-p136-replay-02",
    digestAlgorithmSha256AndQopAuthIntEnforced: true,
    sdpBodyHashMatchesAuthIntEntityBody: true,
    nonceFreshAndNonceCountStrictlyMonotonic: false,
    cnonceEntropyBitsSufficient: false,
    failedAuthAttemptsInWindow: 2,
    maxAllowedFailedAuthAttempts: 5,
  });
  assert.equal(nonceCountReplayBlocked.allowed, false);
  assert.equal(nonceCountReplayBlocked.nonceCountAndCnonceReplaySafe, false);
  assert.equal(
    nonceCountReplayBlocked.actionCode,
    "DROP_REPLAYED_SIP_AUTHORIZATION_AND_CHALLENGE_WITH_FRESH_NONCE_STALE_FALSE"
  );
  assert.equal(
    nonceCountReplayBlocked.reason,
    "RFC3261_SIP_DIGEST_NONCE_COUNT_REPLAY_EXPIRED_NONCE_OR_LOW_ENTROPY_CNONCE_BLOCKED"
  );

  // 3. High-velocity 401/407 credential-stuffing flood exceeding failed auth threshold -> quarantine SIP source IP and rotate secret
  const credentialStuffingBlocked = evaluateSipRfc3261DigestAuthNonceReplayAndQopDowngradeGuard({
    sessionId: "sip-p136-brute-03",
    digestAlgorithmSha256AndQopAuthIntEnforced: true,
    sdpBodyHashMatchesAuthIntEntityBody: true,
    nonceFreshAndNonceCountStrictlyMonotonic: true,
    cnonceEntropyBitsSufficient: true,
    failedAuthAttemptsInWindow: 28,
    maxAllowedFailedAuthAttempts: 5,
  });
  assert.equal(credentialStuffingBlocked.allowed, false);
  assert.equal(credentialStuffingBlocked.credentialStuffingRateWithinBounds, false);
  assert.equal(
    credentialStuffingBlocked.actionCode,
    "QUARANTINE_SIP_SOURCE_IP_TARPIT_403_FORBIDDEN_AND_ROTATE_TRUNK_DIGEST_SECRET"
  );
  assert.equal(
    credentialStuffingBlocked.reason,
    "RFC3261_SIP_DIGEST_CREDENTIAL_STUFFING_OR_BRUTE_FORCE_CHALLENGE_FLOOD_BLOCKED"
  );

  // 4. Healthy RFC 8760 SHA-256 + qop=auth-int SIP Digest request with monotonic nc and high-entropy cnonce -> allow
  const healthySipDigest = evaluateSipRfc3261DigestAuthNonceReplayAndQopDowngradeGuard({
    sessionId: "sip-p136-valid-04",
    digestAlgorithmSha256AndQopAuthIntEnforced: true,
    sdpBodyHashMatchesAuthIntEntityBody: true,
    nonceFreshAndNonceCountStrictlyMonotonic: true,
    cnonceEntropyBitsSufficient: true,
    failedAuthAttemptsInWindow: 0,
    maxAllowedFailedAuthAttempts: 5,
  });
  assert.equal(healthySipDigest.allowed, true);
  assert.equal(healthySipDigest.rfc8760Sha256AndQopAuthIntValid, true);
  assert.equal(healthySipDigest.nonceCountAndCnonceReplaySafe, true);
  assert.equal(healthySipDigest.credentialStuffingRateWithinBounds, true);
  assert.equal(
    healthySipDigest.actionCode,
    "ALLOW_VERIFIED_RFC8760_SIP_DIGEST_AUTHENTICATED_REQUEST"
  );
  assert.equal(
    healthySipDigest.reason,
    "SIP_RFC3261_RFC8760_DIGEST_AUTH_AND_NONCE_INTEGRITY_HEALTHY"
  );
});

