test("P142 WebRTC / RTP RFC 5764 / RFC 7983 DTLS-SRTP first-byte demux collision, DTLS stateless cookie anti-amplification & SDP a=setup deadlock guard blocks demux spoofing, ClientHello amplification and passive-passive deadlock", () => {
  // 1. Malformed first-byte demux collision or invalid RTP version on single-port BUNDLE -> dropped
  const demuxCollisionBlocked =
    evaluateWebrtcRfc5764Rfc7983DtlsSrtpDemuxAndSetupDeadlockGuard({
      sessionId: "BUNDLE-DEMUX-801",
      packetFirstByteMatchesRfc7983DemuxRange: false,
      malformedRtpVersionOnDtlsPort: true,
      unverifiedClientHelloRatePerSec: 12,
      dtlsStatelessCookieVerified: true,
      sdpOfferAndAnswerBothPassiveOrBothActive: false,
      srtpProtectionProfileAndSaltLengthValid: true,
    });
  assert.equal(demuxCollisionBlocked.allowed, false);
  assert.equal(
    demuxCollisionBlocked.policyCode,
    "P142-WEBRTC-RTP-RFC5764-RFC7983-DTLS-SRTP-FIRST-BYTE-DEMUX-COLLISION-HELLO-COOKIE-AMPLIFICATION-DOS-AND-ACTIVE-PASSIVE-SETUP-DEADLOCK-GUARD"
  );
  assert.equal(demuxCollisionBlocked.rfc7983FirstByteDemuxIsolated, false);
  assert.equal(
    demuxCollisionBlocked.actionCode,
    "DROP_MALFORMED_RFC7983_MUX_PACKET_AND_ISOLATE_DTLS_SRTP_PARSER"
  );
  assert.equal(
    demuxCollisionBlocked.reason,
    "RFC7983_SINGLE_PORT_MUX_FIRST_BYTE_COLLISION_OR_MALFORMED_DTLS_RTP_DEMUX_SPOOF_BLOCKED"
  );

  // 2. High-rate unverified DTLS ClientHello flood (>50/s) without stateless Cookie -> blocked to prevent certificate amplification DoS
  const dtlsAmplificationBlocked =
    evaluateWebrtcRfc5764Rfc7983DtlsSrtpDemuxAndSetupDeadlockGuard({
      sessionId: "BUNDLE-COOKIE-802",
      packetFirstByteMatchesRfc7983DemuxRange: true,
      malformedRtpVersionOnDtlsPort: false,
      unverifiedClientHelloRatePerSec: 420,
      dtlsStatelessCookieVerified: false,
      sdpOfferAndAnswerBothPassiveOrBothActive: false,
      srtpProtectionProfileAndSaltLengthValid: true,
    });
  assert.equal(dtlsAmplificationBlocked.allowed, false);
  assert.equal(
    dtlsAmplificationBlocked.dtlsCookieAntiAmplificationEnforced,
    false
  );
  assert.equal(
    dtlsAmplificationBlocked.actionCode,
    "ENFORCE_STATELESS_DTLS_COOKIE_CHALLENGE_AND_SUPPRESS_CERT_CHAIN_AMPLIFICATION"
  );
  assert.equal(
    dtlsAmplificationBlocked.reason,
    "RFC6347_RFC9147_UNVERIFIED_DTLS_CLIENT_HELLO_CERTIFICATE_AMPLIFICATION_FLOOD_BLOCKED"
  );

  // 3. SDP offer/answer both passive (or both active) or SRTP salt length mismatch -> blocked
  const setupDeadlockBlocked =
    evaluateWebrtcRfc5764Rfc7983DtlsSrtpDemuxAndSetupDeadlockGuard({
      sessionId: "BUNDLE-SETUP-803",
      packetFirstByteMatchesRfc7983DemuxRange: true,
      malformedRtpVersionOnDtlsPort: false,
      unverifiedClientHelloRatePerSec: 8,
      dtlsStatelessCookieVerified: true,
      sdpOfferAndAnswerBothPassiveOrBothActive: true,
      srtpProtectionProfileAndSaltLengthValid: false,
    });
  assert.equal(setupDeadlockBlocked.allowed, false);
  assert.equal(setupDeadlockBlocked.sdpSetupRoleAndSrtpSaltValid, false);
  assert.equal(
    setupDeadlockBlocked.actionCode,
    "RESOLVE_SDP_SETUP_ROLE_AND_ENFORCE_RFC5764_SRTP_AEAD_KEY_SALT_DERIVATION"
  );
  assert.equal(
    setupDeadlockBlocked.reason,
    "RFC5763_RFC5764_SDP_SETUP_ROLE_DEADLOCK_OR_SRTP_PROFILE_SALT_LENGTH_DESYNC_BLOCKED"
  );

  // 4. Clean RFC 7983 first-byte demux, verified DTLS cookie, complementary active/passive setup and valid SRTP salt -> allowed
  const healthyDtlsSrtpMux =
    evaluateWebrtcRfc5764Rfc7983DtlsSrtpDemuxAndSetupDeadlockGuard({
      sessionId: "BUNDLE-HEALTHY-804",
      packetFirstByteMatchesRfc7983DemuxRange: true,
      malformedRtpVersionOnDtlsPort: false,
      unverifiedClientHelloRatePerSec: 6,
      dtlsStatelessCookieVerified: true,
      sdpOfferAndAnswerBothPassiveOrBothActive: false,
      srtpProtectionProfileAndSaltLengthValid: true,
    });
  assert.equal(healthyDtlsSrtpMux.allowed, true);
  assert.equal(healthyDtlsSrtpMux.rfc7983FirstByteDemuxIsolated, true);
  assert.equal(healthyDtlsSrtpMux.dtlsCookieAntiAmplificationEnforced, true);
  assert.equal(healthyDtlsSrtpMux.sdpSetupRoleAndSrtpSaltValid, true);
  assert.equal(
    healthyDtlsSrtpMux.actionCode,
    "ALLOW_VERIFIED_RFC5764_RFC7983_DTLS_SRTP_MEDIA_SESSION"
  );
  assert.equal(
    healthyDtlsSrtpMux.reason,
    "WEBRTC_RFC5764_RFC7983_DTLS_SRTP_DEMUX_AND_SETUP_HEALTHY"
  );
});

