test("evaluateSipRfc5626OutboundFlowTokenRfc3327PathLooseRouteAndRfc6665NotifyGuard enforces RFC 5626 flow-token/reg-id, RFC 3327 Path/Route ;lr & RFC 6665 NOTIFY/SUBSCRIBE safety (P150)", () => {
  // 1. Forged RFC 5626 Outbound flow-token HMAC or hijacked +sip.instance / reg-id across unbound TLS tuple -> rejected in 0ms
  const flowTokenHijackBlocked =
    evaluateSipRfc5626OutboundFlowTokenRfc3327PathLooseRouteAndRfc6665NotifyGuard({
      sipOutboundFlowTokenHmacValid: false,
      sipInstanceUuidAndRegIdBoundToTlsTuple: false,
      preloadedRouteOrPathTargetsInternalOrUnallowlistedUri: false,
      looseRoutingLrParameterStrippedOrSpiralDetected: false,
      unsolicitedOutOfDialogNotifyDetected: false,
      activeSubscriptionsPerAorCount: 2,
      maxAllowedSubscriptionsPerAor: 10,
      subscribeExpiresSec: 3600,
    });
  assert.equal(flowTokenHijackBlocked.allowed, false);
  assert.equal(
    flowTokenHijackBlocked.sipOutboundFlowAndRegIdVerified,
    false
  );
  assert.equal(
    flowTokenHijackBlocked.actionCode,
    "REJECT_SIP_403_FORBIDDEN_FLOW_FAILED_PURGE_SPOOFED_BINDING_AND_ALERT_SOC"
  );
  assert.equal(
    flowTokenHijackBlocked.reason,
    "RFC5626_SIP_OUTBOUND_FLOW_TOKEN_HMAC_FORGERY_OR_SIP_INSTANCE_REG_ID_HIJACK_BLOCKED"
  );
  assert.equal(
    flowTokenHijackBlocked.policyCode,
    "P150-SIP-RFC5626-OUTBOUND-FLOW-TOKEN-HIJACK-RFC3327-PATH-ROUTE-OPEN-RELAY-SSRF-AND-RFC6665-UNSOLICITED-NOTIFY-SUBSCRIPTION-STORM-GUARD"
  );

  // 2. Preloaded Route / Path header targeting internal SSRF URI or stripped ;lr loose-routing parameter -> blocked
  const routeSsrfOrSpiralBlocked =
    evaluateSipRfc5626OutboundFlowTokenRfc3327PathLooseRouteAndRfc6665NotifyGuard({
      sipOutboundFlowTokenHmacValid: true,
      sipInstanceUuidAndRegIdBoundToTlsTuple: true,
      preloadedRouteOrPathTargetsInternalOrUnallowlistedUri: true,
      looseRoutingLrParameterStrippedOrSpiralDetected: true,
      unsolicitedOutOfDialogNotifyDetected: false,
      activeSubscriptionsPerAorCount: 2,
      maxAllowedSubscriptionsPerAor: 10,
      subscribeExpiresSec: 3600,
    });
  assert.equal(routeSsrfOrSpiralBlocked.allowed, false);
  assert.equal(
    routeSsrfOrSpiralBlocked.routeAndPathLooseRoutingSafe,
    false
  );
  assert.equal(
    routeSsrfOrSpiralBlocked.actionCode,
    "STRIP_UNTRUSTED_ROUTE_PATH_HEADERS_REJECT_SIP_403_OPEN_RELAY_AND_ENFORCE_EDGE_LR_PINNING"
  );
  assert.equal(
    routeSsrfOrSpiralBlocked.reason,
    "RFC3261_RFC3327_PRELOADED_ROUTE_PATH_OPEN_RELAY_SSRF_OR_STRICT_ROUTING_SPIRAL_BLOCKED"
  );

  // 3. Unsolicited out-of-dialog RFC 6665 NOTIFY or high-frequency SUBSCRIBE storm (Expires < 60s) -> rejected with 481 / 423
  const notifyOrSubscribeStormBlocked =
    evaluateSipRfc5626OutboundFlowTokenRfc3327PathLooseRouteAndRfc6665NotifyGuard({
      sipOutboundFlowTokenHmacValid: true,
      sipInstanceUuidAndRegIdBoundToTlsTuple: true,
      preloadedRouteOrPathTargetsInternalOrUnallowlistedUri: false,
      looseRoutingLrParameterStrippedOrSpiralDetected: false,
      unsolicitedOutOfDialogNotifyDetected: true,
      activeSubscriptionsPerAorCount: 24,
      maxAllowedSubscriptionsPerAor: 10,
      subscribeExpiresSec: 5,
    });
  assert.equal(notifyOrSubscribeStormBlocked.allowed, false);
  assert.equal(
    notifyOrSubscribeStormBlocked.rfc6665SubscriptionAndNotifyHealthy,
    false
  );
  assert.equal(
    notifyOrSubscribeStormBlocked.actionCode,
    "REJECT_SIP_481_OR_423_INTERVAL_TOO_BRIEF_AND_CAP_AOR_SUBSCRIPTION_QUOTA"
  );
  assert.equal(
    notifyOrSubscribeStormBlocked.reason,
    "RFC6665_UNSOLICITED_OUT_OF_DIALOG_NOTIFY_OR_HIGH_FREQUENCY_SUBSCRIBE_AMPLIFICATION_BLOCKED"
  );

  // 4. Verified RFC 5626 flow-token, pinned ;lr Path/Route, and bounded RFC 6665 subscription -> allowed
  const healthySipOutboundAndEvent =
    evaluateSipRfc5626OutboundFlowTokenRfc3327PathLooseRouteAndRfc6665NotifyGuard({
      sipOutboundFlowTokenHmacValid: true,
      sipInstanceUuidAndRegIdBoundToTlsTuple: true,
      preloadedRouteOrPathTargetsInternalOrUnallowlistedUri: false,
      looseRoutingLrParameterStrippedOrSpiralDetected: false,
      unsolicitedOutOfDialogNotifyDetected: false,
      activeSubscriptionsPerAorCount: 3,
      maxAllowedSubscriptionsPerAor: 10,
      subscribeExpiresSec: 1800,
    });
  assert.equal(healthySipOutboundAndEvent.allowed, true);
  assert.equal(
    healthySipOutboundAndEvent.sipOutboundFlowAndRegIdVerified,
    true
  );
  assert.equal(
    healthySipOutboundAndEvent.routeAndPathLooseRoutingSafe,
    true
  );
  assert.equal(
    healthySipOutboundAndEvent.rfc6665SubscriptionAndNotifyHealthy,
    true
  );
  assert.equal(
    healthySipOutboundAndEvent.actionCode,
    "ALLOW_VERIFIED_SIP_OUTBOUND_FLOW_AND_EVENT_DIALOG"
  );
  assert.equal(
    healthySipOutboundAndEvent.reason,
    "SIP_RFC5626_OUTBOUND_RFC3327_PATH_ROUTE_AND_RFC6665_SUBSCRIPTION_HEALTHY"
  );
});

