test("evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard enforces RFC 7741/9626 SVC Dependency Descriptor bounds, keyframe upswitch & layer hysteresis (P152)", () => {
  // 1. Dependency Descriptor template count > 64 or out-of-bounds DTI -> 0ms drop
  const descriptorOverflowBlocked =
    evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard(
      {
        sessionId: "webrtc-svc-sess-01",
        codecType: "AV1-SVC",
        dependencyTemplateCount: 78,
        decodeTargetLayerIndexOutOfBounds: true,
        extensionPayloadBytesExceedRemainingHeader: true,
        currentSpatialLayerId: 1,
        targetSpatialLayerId: 1,
        upswitchOnNonKeyframeWithoutIntraRefresh: false,
        interLayerReferenceBaseDroppedWhileDFlagSet: false,
        spatialLayerSwitchesIn2SecWindow: 0,
      }
    );
  assert.equal(descriptorOverflowBlocked.allowed, false);
  assert.equal(descriptorOverflowBlocked.dependencyDescriptorHeaderSafe, false);
  assert.equal(
    descriptorOverflowBlocked.actionCode,
    "DROP_MALFORMED_RTP_SVC_DEPENDENCY_DESCRIPTOR_PACKET_AND_PRESERVE_SFU_PARSER"
  );
  assert.equal(
    descriptorOverflowBlocked.reason,
    "RFC9626_AV1_SVC_DEPENDENCY_DESCRIPTOR_TEMPLATE_OR_DECODE_TARGET_OVERFLOW_BLOCKED"
  );
  assert.equal(
    descriptorOverflowBlocked.policyCode,
    "P152-WEBRTC-RTP-RFC7741-RFC9626-SVC-VP9-AV1-SPATIAL-TEMPORAL-LAYER-DEPENDENCY-DESCRIPTOR-OVERFLOW-MISSING-KEYFRAME-DISCARD-AND-BITRATE-THRASH-GUARD"
  );

  // 2. Spatial upswitch (S0 -> S2) on non-keyframe or broken base layer with D=1 -> hold S0 and request PLI
  const nonKeyframeUpswitchBlocked =
    evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard(
      {
        sessionId: "webrtc-svc-sess-02",
        codecType: "VP9-SVC",
        dependencyTemplateCount: 12,
        decodeTargetLayerIndexOutOfBounds: false,
        extensionPayloadBytesExceedRemainingHeader: false,
        currentSpatialLayerId: 0,
        targetSpatialLayerId: 2,
        upswitchOnNonKeyframeWithoutIntraRefresh: true,
        interLayerReferenceBaseDroppedWhileDFlagSet: true,
        spatialLayerSwitchesIn2SecWindow: 1,
      }
    );
  assert.equal(nonKeyframeUpswitchBlocked.allowed, false);
  assert.equal(
    nonKeyframeUpswitchBlocked.spatialLayerChainDecodable,
    false
  );
  assert.equal(
    nonKeyframeUpswitchBlocked.actionCode,
    "HOLD_CURRENT_DEC0DABLE_SPATIAL_LAYER_DROP_BROKEN_UPPER_LAYER_AND_SEND_RTCP_PLI"
  );
  assert.equal(
    nonKeyframeUpswitchBlocked.reason,
    "RFC7741_RFC9628_SVC_SPATIAL_UPSWITCH_WITHOUT_KEYFRAME_OR_BROKEN_BASE_LAYER_BLOCKED"
  );

  // 3. Rapid spatial layer oscillation (>3 switches in 2s window) -> hysteresis clamp to temporal scaling
  const oscillationClamped =
    evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard(
      {
        sessionId: "webrtc-svc-sess-03",
        codecType: "AV1-SVC",
        dependencyTemplateCount: 16,
        decodeTargetLayerIndexOutOfBounds: false,
        extensionPayloadBytesExceedRemainingHeader: false,
        currentSpatialLayerId: 1,
        targetSpatialLayerId: 2,
        upswitchOnNonKeyframeWithoutIntraRefresh: false,
        interLayerReferenceBaseDroppedWhileDFlagSet: false,
        spatialLayerSwitchesIn2SecWindow: 6,
      }
    );
  assert.equal(oscillationClamped.allowed, false);
  assert.equal(oscillationClamped.bitrateAdaptationStable, false);
  assert.equal(
    oscillationClamped.actionCode,
    "CLAMP_TO_LOWER_STABLE_SPATIAL_LAYER_AND_ENFORCE_2S_UPSWITCH_HYSTERESIS"
  );
  assert.equal(
    oscillationClamped.reason,
    "SVC_SPATIAL_LAYER_HYSTERESIS_CLAMP_ON_RAPID_BWE_OSCILLATION_APPLIED"
  );

  // 4. Clean keyframe-aligned SVC forwarding
  const healthySvcForwarding =
    evaluateWebrtcRfc7741Rfc9626SvcDependencyDescriptorLayerSwitchAndBitrateThrashGuard(
      {
        sessionId: "webrtc-svc-sess-04",
        codecType: "AV1-SVC",
        dependencyTemplateCount: 16,
        decodeTargetLayerIndexOutOfBounds: false,
        extensionPayloadBytesExceedRemainingHeader: false,
        currentSpatialLayerId: 1,
        targetSpatialLayerId: 2,
        upswitchOnNonKeyframeWithoutIntraRefresh: false,
        interLayerReferenceBaseDroppedWhileDFlagSet: false,
        spatialLayerSwitchesIn2SecWindow: 1,
      }
    );
  assert.equal(healthySvcForwarding.allowed, true);
  assert.equal(
    healthySvcForwarding.actionCode,
    "FORWARD_SVC_SPATIAL_TEMPORAL_LAYER_PACKET"
  );
  assert.equal(
    healthySvcForwarding.reason,
    "WEBRTC_RFC7741_RFC9628_RFC9626_SVC_DEPENDENCY_DESCRIPTOR_AND_LAYER_SWITCH_HEALTHY"
  );
});

