test("evaluateSipRfc3840AutomataLoopRfc3325PaiTrustAndRfc7044HistoryInfoGuard enforces RFC 3840 automata loop breaker, RFC 7044 History-Info guard & RFC 3325 PAI trust stripping (P154)", () => {
  // 1. RFC 3840 / RFC 3841 automata bot-to-bot infinite loop (>2 handshake turns) -> SIP 480 termination
  const botLoopBlocked =
    evaluateSipRfc3840AutomataLoopRfc3325PaiTrustAndRfc7044HistoryInfoGuard({
      callId: "sip-call-p154-01",
      inboundContactDeclaresAutomataOrActorMsgTaker: true,
      localEndpointIsAutomatedVoiceAgent: true,
      botToBotDialogueTurnCount: 5,
      maxAllowedBotToBotHandshakeTurns: 2,
      inboundTrunkInSpecTTrustDomain: true,
      inboundHasPAssertedIdentityOrPPreferredIdentityHeader: false,
      privacyHeaderRequestsIdOrHeaderAnonymity: false,
      outboundTrunkInSpecTTrustDomain: true,
      historyInfoEntryCount: 2,
      maxAllowedHistoryInfoEntries: 8,
      historyInfoContainsCircularRetargetingOrPrivilegeEscalationUri: false,
    });
  assert.equal(botLoopBlocked.allowed, false);
  assert.equal(botLoopBlocked.sipResponseCode, 480);
  assert.equal(
    botLoopBlocked.policyCode,
    "P154-SIP-RFC3840-RFC3841-AUTOMATA-BOT-LOOP-RFC3325-PAI-PRIVACY-TRUNK-TRUST-AND-RFC7044-HISTORY-INFO-RETARGET-GUARD"
  );
  assert.equal(
    botLoopBlocked.actionCode,
    "TERMINATE_RFC3840_AUTOMATA_BOT_TO_BOT_LOOP_WITH_SIP_480"
  );
  assert.equal(
    botLoopBlocked.reason,
    "RFC3840_RFC3841_SIP_AUTOMATA_FEATURE_TAG_BOT_TO_BOT_INFINITE_LOOP_BLOCKED"
  );

  // 2. RFC 4244 / RFC 7044 History-Info circular retargeting or depth overflow -> SIP 482 Loop Detected
  const historyInfoLoopBlocked =
    evaluateSipRfc3840AutomataLoopRfc3325PaiTrustAndRfc7044HistoryInfoGuard({
      callId: "sip-call-p154-02",
      inboundContactDeclaresAutomataOrActorMsgTaker: false,
      localEndpointIsAutomatedVoiceAgent: true,
      botToBotDialogueTurnCount: 0,
      maxAllowedBotToBotHandshakeTurns: 2,
      inboundTrunkInSpecTTrustDomain: true,
      inboundHasPAssertedIdentityOrPPreferredIdentityHeader: false,
      privacyHeaderRequestsIdOrHeaderAnonymity: false,
      outboundTrunkInSpecTTrustDomain: true,
      historyInfoEntryCount: 12,
      maxAllowedHistoryInfoEntries: 8,
      historyInfoContainsCircularRetargetingOrPrivilegeEscalationUri: true,
    });
  assert.equal(historyInfoLoopBlocked.allowed, false);
  assert.equal(historyInfoLoopBlocked.sipResponseCode, 482);
  assert.equal(historyInfoLoopBlocked.historyInfoRetargetingBlocked, true);
  assert.equal(
    historyInfoLoopBlocked.actionCode,
    "REJECT_RFC7044_HISTORY_INFO_LOOP_OR_PRIVILEGE_ESCALATION_WITH_SIP_482"
  );
  assert.equal(
    historyInfoLoopBlocked.reason,
    "RFC7044_SIP_HISTORY_INFO_RETARGETING_DEPTH_OVERFLOW_OR_PRIVILEGE_ESCALATION_BLOCKED"
  );

  // 3. RFC 3323 / RFC 3325 untrusted ingress PAI spoof or Privacy: id egress leak -> strip/redact PAI
  const paiSanitized =
    evaluateSipRfc3840AutomataLoopRfc3325PaiTrustAndRfc7044HistoryInfoGuard({
      callId: "sip-call-p154-03",
      inboundContactDeclaresAutomataOrActorMsgTaker: false,
      localEndpointIsAutomatedVoiceAgent: true,
      botToBotDialogueTurnCount: 0,
      maxAllowedBotToBotHandshakeTurns: 2,
      inboundTrunkInSpecTTrustDomain: false,
      inboundHasPAssertedIdentityOrPPreferredIdentityHeader: true,
      privacyHeaderRequestsIdOrHeaderAnonymity: true,
      outboundTrunkInSpecTTrustDomain: false,
      historyInfoEntryCount: 2,
      maxAllowedHistoryInfoEntries: 8,
      historyInfoContainsCircularRetargetingOrPrivilegeEscalationUri: false,
    });
  assert.equal(paiSanitized.allowed, false);
  assert.equal(paiSanitized.untrustedPaiStrippedAtIngress, true);
  assert.equal(paiSanitized.outboundPaiRedactedForPrivacyId, true);
  assert.equal(
    paiSanitized.actionCode,
    "STRIP_UNTRUSTED_OR_PRIVACY_RESTRICTED_RFC3325_PAI_HEADER"
  );
  assert.equal(
    paiSanitized.reason,
    "RFC3323_RFC3325_UNTRUSTED_INGRESS_PAI_SPOOF_OR_EGRESS_PRIVACY_ID_LEAK_SANITIZED"
  );

  // 4. Clean verified SIP routing
  const healthySip =
    evaluateSipRfc3840AutomataLoopRfc3325PaiTrustAndRfc7044HistoryInfoGuard({
      callId: "sip-call-p154-04",
      inboundContactDeclaresAutomataOrActorMsgTaker: false,
      localEndpointIsAutomatedVoiceAgent: true,
      botToBotDialogueTurnCount: 0,
      maxAllowedBotToBotHandshakeTurns: 2,
      inboundTrunkInSpecTTrustDomain: true,
      inboundHasPAssertedIdentityOrPPreferredIdentityHeader: true,
      privacyHeaderRequestsIdOrHeaderAnonymity: false,
      outboundTrunkInSpecTTrustDomain: true,
      historyInfoEntryCount: 2,
      maxAllowedHistoryInfoEntries: 8,
      historyInfoContainsCircularRetargetingOrPrivilegeEscalationUri: false,
    });
  assert.equal(healthySip.allowed, true);
  assert.equal(healthySip.sipResponseCode, 200);
  assert.equal(healthySip.actionCode, "ALLOW_VERIFIED_SIP_CALL_ROUTING");
  assert.equal(
    healthySip.reason,
    "SIP_RFC3840_AUTOMATA_RFC3325_PAI_AND_RFC7044_HISTORY_INFO_VERIFIED"
  );
});

