test("evaluateSipRfc3326ReasonHeaderQ850CauseSpoofingRfc3329SecAgreeDowngradeAndSip420BadExtensionLoopGuard enforces RFC 3329 sec-agree 494, RFC 3326 Q.850 stripping & RFC 3261 420 loop guard (P162)", () => {
  // 1. RFC 3329 Security-Verify mismatch or sec-agree downgrade to null/plaintext -> SIP 494 reject
  const secAgreeDowngradeBlocked =
    evaluateSipRfc3326ReasonHeaderQ850CauseSpoofingRfc3329SecAgreeDowngradeAndSip420BadExtensionLoopGuard({
      sipDialogId: "sip-p162-dlg-01",
      rfc3329SecurityVerifyMatchesNegotiatedServerPolicy: false,
      secAgreeProposedMechanismDowngradedToNullOrPlaintext: true,
      reasonHeaderPresentOnInboundOrResponseMessage: false,
      trunkTrustedForRfc3326Q850CausePassThrough: true,
      q850CauseContradictsSipResponseCodeClass: false,
      unrecognizedRequireOrProxyRequireOptionTagPresent: false,
      badExtension420RetryCount: 0,
      maxAllowedBadExtension420Retries: 1,
    });
  assert.equal(secAgreeDowngradeBlocked.allowed, false);
  assert.equal(secAgreeDowngradeBlocked.rfc3329SecAgreeDowngradeOrMismatchRejected494, true);
  assert.equal(
    secAgreeDowngradeBlocked.policyCode,
    "P162-SIP-RFC3326-REASON-HEADER-Q850-CAUSE-SPOOFING-RFC3329-SEC-AGREE-DOWNGRADE-AND-SIP-420-BAD-EXTENSION-LOOP-GUARD"
  );
  assert.equal(
    secAgreeDowngradeBlocked.actionCode,
    "REJECT_SIP_494_SECURITY_AGREEMENT_REQUIRED_ON_RFC3329_TAMPER_OR_DOWNGRADE"
  );
  assert.equal(
    secAgreeDowngradeBlocked.reason,
    "RFC3329_SEC_AGREE_SECURITY_VERIFY_MISMATCH_OR_PLAINTEXT_DOWNGRADE_REJECTED_494"
  );

  // 2. Untrusted trunk or contradictory Q.850 cause code in RFC 3326 Reason header -> strip & map local cause
  const spoofedQ850Stripped =
    evaluateSipRfc3326ReasonHeaderQ850CauseSpoofingRfc3329SecAgreeDowngradeAndSip420BadExtensionLoopGuard({
      sipDialogId: "sip-p162-dlg-02",
      rfc3329SecurityVerifyMatchesNegotiatedServerPolicy: true,
      secAgreeProposedMechanismDowngradedToNullOrPlaintext: false,
      reasonHeaderPresentOnInboundOrResponseMessage: true,
      trunkTrustedForRfc3326Q850CausePassThrough: false,
      q850CauseContradictsSipResponseCodeClass: true,
      unrecognizedRequireOrProxyRequireOptionTagPresent: false,
      badExtension420RetryCount: 0,
      maxAllowedBadExtension420Retries: 1,
    });
  assert.equal(spoofedQ850Stripped.allowed, false);
  assert.equal(spoofedQ850Stripped.untrustedRfc3326Q850ReasonHeaderStripped, true);
  assert.equal(
    spoofedQ850Stripped.actionCode,
    "STRIP_UNTRUSTED_RFC3326_REASON_HEADER_AND_MAP_AUTHORITATIVE_LOCAL_Q850_CAUSE"
  );
  assert.equal(
    spoofedQ850Stripped.reason,
    "RFC3326_RFC6432_UNTRUSTED_OR_CONTRADICTORY_Q850_REASON_HEADER_SPOOFING_STRIPPED"
  );

  // 3. Unrecognized Require / Proxy-Require option-tag or 420 Bad Extension retry loop -> 420 reject & halt
  const badExtensionLoopBlocked =
    evaluateSipRfc3326ReasonHeaderQ850CauseSpoofingRfc3329SecAgreeDowngradeAndSip420BadExtensionLoopGuard({
      sipDialogId: "sip-p162-dlg-03",
      rfc3329SecurityVerifyMatchesNegotiatedServerPolicy: true,
      secAgreeProposedMechanismDowngradedToNullOrPlaintext: false,
      reasonHeaderPresentOnInboundOrResponseMessage: false,
      trunkTrustedForRfc3326Q850CausePassThrough: true,
      q850CauseContradictsSipResponseCodeClass: false,
      unrecognizedRequireOrProxyRequireOptionTagPresent: true,
      badExtension420RetryCount: 3,
      maxAllowedBadExtension420Retries: 1,
    });
  assert.equal(badExtensionLoopBlocked.allowed, false);
  assert.equal(badExtensionLoopBlocked.unsupportedRequireOptionTagRejected420OrHalted, true);
  assert.equal(
    badExtensionLoopBlocked.actionCode,
    "REJECT_SIP_420_BAD_EXTENSION_AND_HALT_UNSUPPORTED_OPTION_TAG_RETRY_LOOP"
  );
  assert.equal(
    badExtensionLoopBlocked.reason,
    "RFC3261_UNSUPPORTED_REQUIRE_OPTION_TAG_OR_420_BAD_EXTENSION_RETRY_LOOP_BLOCKED"
  );

  // 4. Compliant SIP RFC 3326 / RFC 3329 signaling transaction
  const compliantSipReasonSecAgree =
    evaluateSipRfc3326ReasonHeaderQ850CauseSpoofingRfc3329SecAgreeDowngradeAndSip420BadExtensionLoopGuard({
      sipDialogId: "sip-p162-dlg-04",
      rfc3329SecurityVerifyMatchesNegotiatedServerPolicy: true,
      secAgreeProposedMechanismDowngradedToNullOrPlaintext: false,
      reasonHeaderPresentOnInboundOrResponseMessage: true,
      trunkTrustedForRfc3326Q850CausePassThrough: true,
      q850CauseContradictsSipResponseCodeClass: false,
      unrecognizedRequireOrProxyRequireOptionTagPresent: false,
      badExtension420RetryCount: 0,
      maxAllowedBadExtension420Retries: 1,
    });
  assert.equal(compliantSipReasonSecAgree.allowed, true);
  assert.equal(
    compliantSipReasonSecAgree.actionCode,
    "ALLOW_VERIFIED_RFC3326_RFC3329_SIP_SIGNALING_TRANSACTION"
  );
  assert.equal(
    compliantSipReasonSecAgree.reason,
    "SIP_RFC3326_Q850_REASON_RFC3329_SEC_AGREE_AND_OPTION_TAGS_VERIFIED"
  );
});

