test("evaluateWebrtcRtpRfc8285ExtmapAllowMixedOneTwoByteHeaderConfusionUriRemapAndPaddingOverflowGuard enforces RFC 8285 0xBEDE/0x1000 profile isolation, immutable extmap URI binding & word-length/padding bounds (P164)", () => {
  // 1. Two-byte 0x1000 extension ID > 14 without a=extmap-allow-mixed or One-byte 0xBEDE reserved ID=15/L=0 abuse -> strip malformed extension
  const profileOrId15AbuseDropped =
    evaluateWebrtcRtpRfc8285ExtmapAllowMixedOneTwoByteHeaderConfusionUriRemapAndPaddingOverflowGuard({
      rtpStreamId: "rtp-p164-ext-01",
      extensionProfileDefinedBy0xBEDEOneByte: true,
      extensionProfileDefinedBy0x1000TwoByte: false,
      sdpExtmapAllowMixedNegotiated: false,
      extensionId: 15,
      oneByteExtensionElementLengthZeroOrReservedId15UsedForData: true,
      ssrcStreamActive: true,
      extmapIdReboundToDifferentUriMidCallWithoutSsrcReset: false,
      extensionHeaderDeclaredWordLengthTimes4: 8,
      remainingPacketBytesBeforePayload: 64,
      nonZeroExtensionPaddingBytesDetected: false,
    });
  assert.equal(profileOrId15AbuseDropped.allowed, false);
  assert.equal(profileOrId15AbuseDropped.rfc8285OneTwoByteProfileOrReservedId15ViolationDropped, true);
  assert.equal(
    profileOrId15AbuseDropped.policyCode,
    "P164-WEBRTC-RTP-RFC5285-EXTMAP-ALLOW-MIXED-ONE-TWO-BYTE-HEADER-EXTENSION-CONFUSION-URI-ID-REMAPPING-DESYNC-AND-PADDING-OVERFLOW-GUARD"
  );
  assert.equal(
    profileOrId15AbuseDropped.actionCode,
    "STRIP_MALFORMED_RFC8285_HEADER_EXTENSION_ON_PROFILE_OR_ID15_VIOLATION"
  );
  assert.equal(
    profileOrId15AbuseDropped.reason,
    "RFC8285_ONE_TWO_BYTE_PROFILE_MISMATCH_UNNEGOTIATED_ALLOW_MIXED_OR_RESERVED_ID15_ABUSE_BLOCKED"
  );

  // 2. Mid-call SDP re-INVITE rebinding active extmap ID to a different URI without SSRC reset -> reject remapping
  const midCallUriRemapRejected =
    evaluateWebrtcRtpRfc8285ExtmapAllowMixedOneTwoByteHeaderConfusionUriRemapAndPaddingOverflowGuard({
      rtpStreamId: "rtp-p164-ext-02",
      extensionProfileDefinedBy0xBEDEOneByte: true,
      extensionProfileDefinedBy0x1000TwoByte: false,
      sdpExtmapAllowMixedNegotiated: true,
      extensionId: 3,
      oneByteExtensionElementLengthZeroOrReservedId15UsedForData: false,
      ssrcStreamActive: true,
      extmapIdReboundToDifferentUriMidCallWithoutSsrcReset: true,
      extensionHeaderDeclaredWordLengthTimes4: 8,
      remainingPacketBytesBeforePayload: 64,
      nonZeroExtensionPaddingBytesDetected: false,
    });
  assert.equal(midCallUriRemapRejected.allowed, false);
  assert.equal(midCallUriRemapRejected.midCallExtmapIdUriRemappingRejected, true);
  assert.equal(
    midCallUriRemapRejected.actionCode,
    "REJECT_SDP_EXTMAP_ID_URI_REMAPPING_AND_PRESERVE_IMMUTABLE_ID_BINDING"
  );
  assert.equal(
    midCallUriRemapRejected.reason,
    "RFC8285_RFC8829_MID_CALL_EXTMAP_ID_URI_COLLISION_REMAPPING_WITHOUT_RESET_BLOCKED"
  );

  // 3. Declared extension word length * 4 exceeds remaining packet bytes or non-zero padding covert channel -> drop RTP packet
  const wordLengthOrDirtyPaddingDropped =
    evaluateWebrtcRtpRfc8285ExtmapAllowMixedOneTwoByteHeaderConfusionUriRemapAndPaddingOverflowGuard({
      rtpStreamId: "rtp-p164-ext-03",
      extensionProfileDefinedBy0xBEDEOneByte: false,
      extensionProfileDefinedBy0x1000TwoByte: true,
      sdpExtmapAllowMixedNegotiated: true,
      extensionId: 42,
      oneByteExtensionElementLengthZeroOrReservedId15UsedForData: false,
      ssrcStreamActive: true,
      extmapIdReboundToDifferentUriMidCallWithoutSsrcReset: false,
      extensionHeaderDeclaredWordLengthTimes4: 256,
      remainingPacketBytesBeforePayload: 48,
      nonZeroExtensionPaddingBytesDetected: true,
    });
  assert.equal(wordLengthOrDirtyPaddingDropped.allowed, false);
  assert.equal(wordLengthOrDirtyPaddingDropped.extensionWordLengthOverflowOrNonZeroPaddingDropped, true);
  assert.equal(
    wordLengthOrDirtyPaddingDropped.actionCode,
    "DROP_RTP_PACKET_ON_RFC8285_EXTENSION_LENGTH_OVERFLOW_OR_DIRTY_PADDING"
  );
  assert.equal(
    wordLengthOrDirtyPaddingDropped.reason,
    "RFC8285_EXTENSION_WORD_LENGTH_PACKET_OOB_OR_NONZERO_PADDING_COVERT_CHANNEL_BLOCKED"
  );

  // 4. Compliant RFC 8285 RTP header extension packet
  const compliantRfc8285Packet =
    evaluateWebrtcRtpRfc8285ExtmapAllowMixedOneTwoByteHeaderConfusionUriRemapAndPaddingOverflowGuard({
      rtpStreamId: "rtp-p164-ext-04",
      extensionProfileDefinedBy0xBEDEOneByte: false,
      extensionProfileDefinedBy0x1000TwoByte: true,
      sdpExtmapAllowMixedNegotiated: true,
      extensionId: 24,
      oneByteExtensionElementLengthZeroOrReservedId15UsedForData: false,
      ssrcStreamActive: true,
      extmapIdReboundToDifferentUriMidCallWithoutSsrcReset: false,
      extensionHeaderDeclaredWordLengthTimes4: 12,
      remainingPacketBytesBeforePayload: 96,
      nonZeroExtensionPaddingBytesDetected: false,
    });
  assert.equal(compliantRfc8285Packet.allowed, true);
  assert.equal(
    compliantRfc8285Packet.actionCode,
    "ALLOW_VERIFIED_RFC8285_RTP_HEADER_EXTENSION_PACKET"
  );
  assert.equal(
    compliantRfc8285Packet.reason,
    "WEBRTC_RTP_RFC8285_HEADER_EXTENSION_PROFILE_URI_MAP_AND_BOUNDS_VERIFIED"
  );
});

