test("evaluateSipSdpRfc8866Rfc4568SdesInlineKeyLeakConnectionSinkholeAndFmtpOverflowGuard enforces RFC 8866 / RFC 4568 SDES inline master-key protection, c= amplification sinkhole block & a=fmtp bounds (P166)", () => {
  // 1. RFC 4568 a=crypto SDES inline master key over cleartext SIP or dual DTLS+SDES conflict -> scrub SDES key & reject SIP 488
  const sdesKeyLeakBlocked =
    evaluateSipSdpRfc8866Rfc4568SdesInlineKeyLeakConnectionSinkholeAndFmtpOverflowGuard({
      sdpSessionId: "sdp-p166-sess-01",
      sdpContainsRfc4568SdesCryptoInlineKey: true,
      sipSignalingOverVerifiedTlsOrSips: false,
      dtlsSrtpAlreadyNegotiatedOnMediaSection: true,
      sdpConnectionAddressIsBroadcastMulticastLoopbackOrRfc1918OnPublicTrunk: false,
      explicitRfc3264HoldZeroAddressValid: false,
      sdpLineByteLength: 240,
      maxAllowedSdpLineBytes: 1024,
      fmtpAttributeParameterCount: 6,
      maxAllowedFmtpParameters: 32,
      duplicatePayloadTypeMappingInSingleMLine: false,
    });
  assert.equal(sdesKeyLeakBlocked.allowed, false);
  assert.equal(sdesKeyLeakBlocked.rfc4568SdesInlineKeyLeakOrDtlsDualCryptoRejected, true);
  assert.equal(
    sdesKeyLeakBlocked.policyCode,
    "P166-SIP-SDP-RFC8866-RFC4568-SDES-CRYPTO-INLINE-KEY-LEAK-CONNECTION-ADDRESS-AMPLIFICATION-SINKHOLE-AND-FMTP-LINE-OVERFLOW-GUARD"
  );
  assert.equal(
    sdesKeyLeakBlocked.actionCode,
    "SCRUB_SDES_INLINE_KEY_REJECT_SIP_488_AND_ENFORCE_DTLS_SRTP_ONLY"
  );
  assert.equal(
    sdesKeyLeakBlocked.reason,
    "RFC4568_RFC8829_SDES_INLINE_MASTER_KEY_OVER_CLEARTEXT_SIP_OR_DUAL_DTLS_SDES_CONFLICT_BLOCKED"
  );

  // 2. SDP c=IN IP4/IP6 connection address pointing to broadcast/multicast/loopback/RFC1918 on public trunk -> reject sinkhole & pin RTP to SBC peer
  const connectionSinkholeBlocked =
    evaluateSipSdpRfc8866Rfc4568SdesInlineKeyLeakConnectionSinkholeAndFmtpOverflowGuard({
      sdpSessionId: "sdp-p166-sess-02",
      sdpContainsRfc4568SdesCryptoInlineKey: false,
      sipSignalingOverVerifiedTlsOrSips: true,
      dtlsSrtpAlreadyNegotiatedOnMediaSection: true,
      sdpConnectionAddressIsBroadcastMulticastLoopbackOrRfc1918OnPublicTrunk: true,
      explicitRfc3264HoldZeroAddressValid: false,
      sdpLineByteLength: 240,
      maxAllowedSdpLineBytes: 1024,
      fmtpAttributeParameterCount: 6,
      maxAllowedFmtpParameters: 32,
      duplicatePayloadTypeMappingInSingleMLine: false,
    });
  assert.equal(connectionSinkholeBlocked.allowed, false);
  assert.equal(connectionSinkholeBlocked.sdpConnectionAddressAmplificationOrSinkholeBlocked, true);
  assert.equal(
    connectionSinkholeBlocked.actionCode,
    "REJECT_SDP_CONNECTION_SINKHOLE_AND_PIN_RTP_TO_VERIFIED_SBC_PEER"
  );
  assert.equal(
    connectionSinkholeBlocked.reason,
    "RFC8866_SDP_CONNECTION_ADDRESS_BROADCAST_LOOPBACK_OR_SSRF_MEDIA_AMPLIFICATION_TARGET_BLOCKED"
  );

  // 3. SDP line byte length overflow, a=fmtp parameter bomb, or duplicate payload type in m= line -> drop malformed SDP
  const fmtpOrPtOverflowDropped =
    evaluateSipSdpRfc8866Rfc4568SdesInlineKeyLeakConnectionSinkholeAndFmtpOverflowGuard({
      sdpSessionId: "sdp-p166-sess-03",
      sdpContainsRfc4568SdesCryptoInlineKey: false,
      sipSignalingOverVerifiedTlsOrSips: true,
      dtlsSrtpAlreadyNegotiatedOnMediaSection: true,
      sdpConnectionAddressIsBroadcastMulticastLoopbackOrRfc1918OnPublicTrunk: false,
      explicitRfc3264HoldZeroAddressValid: false,
      sdpLineByteLength: 8192,
      maxAllowedSdpLineBytes: 1024,
      fmtpAttributeParameterCount: 128,
      maxAllowedFmtpParameters: 32,
      duplicatePayloadTypeMappingInSingleMLine: true,
    });
  assert.equal(fmtpOrPtOverflowDropped.allowed, false);
  assert.equal(fmtpOrPtOverflowDropped.sdpFmtpLineOverflowOrDuplicatePtDropped, true);
  assert.equal(
    fmtpOrPtOverflowDropped.actionCode,
    "DROP_MALFORMED_SDP_OFFER_ANSWER_ON_RFC8866_FMTP_OR_PT_OVERFLOW"
  );
  assert.equal(
    fmtpOrPtOverflowDropped.reason,
    "RFC8866_SDP_LINE_LENGTH_OVERFLOW_FMTP_PARAMETER_BOMB_OR_DUPLICATE_RTPMAP_PT_BLOCKED"
  );

  // 4. Compliant RFC 8866 SDP session description
  const compliantRfc8866Sdp =
    evaluateSipSdpRfc8866Rfc4568SdesInlineKeyLeakConnectionSinkholeAndFmtpOverflowGuard({
      sdpSessionId: "sdp-p166-sess-04",
      sdpContainsRfc4568SdesCryptoInlineKey: false,
      sipSignalingOverVerifiedTlsOrSips: true,
      dtlsSrtpAlreadyNegotiatedOnMediaSection: true,
      sdpConnectionAddressIsBroadcastMulticastLoopbackOrRfc1918OnPublicTrunk: false,
      explicitRfc3264HoldZeroAddressValid: false,
      sdpLineByteLength: 312,
      maxAllowedSdpLineBytes: 1024,
      fmtpAttributeParameterCount: 8,
      maxAllowedFmtpParameters: 32,
      duplicatePayloadTypeMappingInSingleMLine: false,
    });
  assert.equal(compliantRfc8866Sdp.allowed, true);
  assert.equal(
    compliantRfc8866Sdp.actionCode,
    "ALLOW_VERIFIED_RFC8866_SDP_SESSION_DESCRIPTION"
  );
  assert.equal(
    compliantRfc8866Sdp.reason,
    "SIP_SDP_RFC8866_RFC4568_CRYPTO_CONNECTION_ADDRESS_AND_FMTP_BOUNDS_VERIFIED"
  );
});

