test("evaluateWebrtcRtcpRfc3550CompoundPacketSrRrFirstSdesCnameBoundsPaddingUnderflowAndByeFloodGuard enforces RFC 3550 / RFC 5506 SR/RR first-subpacket rule, word-length/padding bounds & SDES CNAME / BYE flood defense (P168)", () => {
  // 1. Non-compound RTCP packet starting with PT != 200 (SR) / 201 (RR) without negotiated RFC 5506 a=rtcp-rsize -> drop
  const invalidFirstSubpacketDropped =
    evaluateWebrtcRtcpRfc3550CompoundPacketSrRrFirstSdesCnameBoundsPaddingUnderflowAndByeFloodGuard({
      firstRtcpSubpacketPayloadType: 202,
      rfc5506ReducedSizeRtcpNegotiatedInSdp: false,
      sumOfSubpacketHeaderDeclaredBytes: 96,
      actualUdpDatagramTotalBytes: 96,
      lastSubpacketPaddingBitSet: false,
      lastSubpacketFinalPaddingOctetValue: 0,
      lastSubpacketPayloadBodyBytes: 32,
      compoundIncludesSdesChunkWithCname: true,
      sdesCnameItemLengthBytes: 24,
      rtcpByePacketsReceivedPerSecond: 1,
      maxAllowedByePacketsPerSecond: 10,
      rtcpByeSsrcCountInPacket: 1,
      maxAllowedByeSsrcsPerPacket: 4,
    });
  assert.equal(invalidFirstSubpacketDropped.allowed, false);
  assert.equal(invalidFirstSubpacketDropped.nonCompoundOrInvalidFirstPtDropped, true);
  assert.equal(
    invalidFirstSubpacketDropped.policyCode,
    "P168-WEBRTC-RTCP-RFC3550-COMPOUND-PACKET-SR-RR-FIRST-RULE-SDES-CNAME-OVERFLOW-PADDING-UNDERFLOW-AND-BYE-FLOOD-GUARD"
  );
  assert.equal(
    invalidFirstSubpacketDropped.actionCode,
    "DROP_NON_COMPLIANT_RTCP_PACKET_AND_PRESERVE_JITTER_BUFFER_SYNCHRONIZATION_STATE"
  );
  assert.equal(
    invalidFirstSubpacketDropped.reason,
    "RFC3550_COMPOUND_RTCP_FIRST_SUBPACKET_NOT_SR_200_OR_RR_201_WITHOUT_NEGOTIATED_RFC5506_RSIZE"
  );

  // 2. 32-bit word-length sum mismatch or P=1 trailing padding octet integer underflow -> drop malformed packet
  const paddingUnderflowDropped =
    evaluateWebrtcRtcpRfc3550CompoundPacketSrRrFirstSdesCnameBoundsPaddingUnderflowAndByeFloodGuard({
      firstRtcpSubpacketPayloadType: 200,
      rfc5506ReducedSizeRtcpNegotiatedInSdp: false,
      sumOfSubpacketHeaderDeclaredBytes: 128,
      actualUdpDatagramTotalBytes: 92,
      lastSubpacketPaddingBitSet: true,
      lastSubpacketFinalPaddingOctetValue: 255,
      lastSubpacketPayloadBodyBytes: 28,
      compoundIncludesSdesChunkWithCname: true,
      sdesCnameItemLengthBytes: 24,
      rtcpByePacketsReceivedPerSecond: 1,
      maxAllowedByePacketsPerSecond: 10,
      rtcpByeSsrcCountInPacket: 1,
      maxAllowedByeSsrcsPerPacket: 4,
    });
  assert.equal(paddingUnderflowDropped.allowed, false);
  assert.equal(paddingUnderflowDropped.wordLengthMismatchOrPaddingUnderflowDropped, true);
  assert.equal(
    paddingUnderflowDropped.actionCode,
    "DROP_TRUNCATED_OR_PADDED_BLEED_RTCP_DATAGRAM_BEFORE_SUBPACKET_ITERATOR"
  );
  assert.equal(
    paddingUnderflowDropped.reason,
    "RFC3550_RTCP_32BIT_WORD_LENGTH_SUM_MISMATCH_OR_PADDING_OCTET_INTEGER_UNDERFLOW_BLOCKED"
  );

  // 3. Missing/oversized SDES CNAME (>255B) or RTCP BYE SSRC churn flood -> throttle & block
  const sdesOrByeFloodBlocked =
    evaluateWebrtcRtcpRfc3550CompoundPacketSrRrFirstSdesCnameBoundsPaddingUnderflowAndByeFloodGuard({
      firstRtcpSubpacketPayloadType: 201,
      rfc5506ReducedSizeRtcpNegotiatedInSdp: false,
      sumOfSubpacketHeaderDeclaredBytes: 112,
      actualUdpDatagramTotalBytes: 112,
      lastSubpacketPaddingBitSet: false,
      lastSubpacketFinalPaddingOctetValue: 0,
      lastSubpacketPayloadBodyBytes: 48,
      compoundIncludesSdesChunkWithCname: false,
      sdesCnameItemLengthBytes: 0,
      rtcpByePacketsReceivedPerSecond: 48,
      maxAllowedByePacketsPerSecond: 10,
      rtcpByeSsrcCountInPacket: 24,
      maxAllowedByeSsrcsPerPacket: 4,
    });
  assert.equal(sdesOrByeFloodBlocked.allowed, false);
  assert.equal(sdesOrByeFloodBlocked.missingOrOversizedSdesCnameOrByeFloodBlocked, true);
  assert.equal(
    sdesOrByeFloodBlocked.actionCode,
    "REJECT_MALFORMED_SDES_CNAME_AND_RATE_LIMIT_UNAUTHENTICATED_RTCP_BYE_CHURN"
  );
  assert.equal(
    sdesOrByeFloodBlocked.reason,
    "RFC3550_RTCP_BYE_SSRC_CHURN_AMPLIFICATION_FLOOD_THROTTLED"
  );

  // 4. Compliant RFC 3550 compound RTCP packet
  const compliantCompoundRtcp =
    evaluateWebrtcRtcpRfc3550CompoundPacketSrRrFirstSdesCnameBoundsPaddingUnderflowAndByeFloodGuard({
      firstRtcpSubpacketPayloadType: 200,
      rfc5506ReducedSizeRtcpNegotiatedInSdp: false,
      sumOfSubpacketHeaderDeclaredBytes: 96,
      actualUdpDatagramTotalBytes: 96,
      lastSubpacketPaddingBitSet: true,
      lastSubpacketFinalPaddingOctetValue: 4,
      lastSubpacketPayloadBodyBytes: 36,
      compoundIncludesSdesChunkWithCname: true,
      sdesCnameItemLengthBytes: 24,
      rtcpByePacketsReceivedPerSecond: 1,
      maxAllowedByePacketsPerSecond: 10,
      rtcpByeSsrcCountInPacket: 1,
      maxAllowedByeSsrcsPerPacket: 4,
    });
  assert.equal(compliantCompoundRtcp.allowed, true);
  assert.equal(
    compliantCompoundRtcp.actionCode,
    "ALLOW_VERIFIED_RFC3550_COMPOUND_RTCP_PACKET"
  );
  assert.equal(
    compliantCompoundRtcp.reason,
    "WEBRTC_RTCP_RFC3550_COMPOUND_SR_RR_WORD_LENGTH_SDES_CNAME_AND_BYE_RATE_VERIFIED"
  );
});

