test("evaluateSipRfc3261Rfc3581Rfc5626ViaHeaderChainAmplificationBranchCollisionAndFlowTokenHijackGuard enforces Via rport reflection defense, Via chain/z9hG4bK bounds & Outbound flow-token security (P170)", () => {
  // 1. Untrusted endpoint spoofing Via sent-by with pre-populated received=/rport= -> strip and pin source tuple
  const viaReflectionBlocked =
    evaluateSipRfc3261Rfc3581Rfc5626ViaHeaderChainAmplificationBranchCollisionAndFlowTokenHijackGuard({
      topmostViaSentByHostMatchesSourceIp: false,
      untrustedEndpointPrePopulatedReceivedOrRport: true,
      viaHeaderHopCount: 2,
      maxAllowedViaHeaderHops: 16,
      totalViaHeaderBlockBytes: 320,
      maxAllowedViaHeaderBlockBytes: 4096,
      topmostViaBranchStartsWithZ9hG4bK: true,
      duplicateViaBranchWithMismatchedCseqMethodOrSentBy: false,
      rfc5626OutboundFlowTokenPresent: false,
      outboundFlowTokenHmacVerified: true,
      flowTokenBoundTlsTupleMatchesActiveConnection: true,
      recordRouteAttemptsTlsToUdpCleartextDowngrade: false,
    });
  assert.equal(viaReflectionBlocked.allowed, false);
  assert.equal(viaReflectionBlocked.viaRportOrReceivedReflectionBlocked, true);
  assert.equal(
    viaReflectionBlocked.policyCode,
    "P170-SIP-RFC3261-RFC3581-RFC5626-VIA-HEADER-CHAIN-AMPLIFICATION-RPORT-SPOOF-BRANCH-COLLISION-AND-OUTBOUND-FLOW-TOKEN-HIJACK-GUARD"
  );
  assert.equal(
    viaReflectionBlocked.actionCode,
    "STRIP_UNTRUSTED_VIA_RECEIVED_RPORT_PIN_SYMMETRIC_SOURCE_TUPLE_AND_DROP_REFLECTION_PROBE"
  );
  assert.equal(
    viaReflectionBlocked.reason,
    "RFC3581_RFC3261_TOPMOST_VIA_SENT_BY_OR_PREPOPULATED_RECEIVED_RPORT_REFLECTION_SPOOF_BLOCKED"
  );

  // 2. Excessive Via header chain (>16 hops / >4096B) or missing z9hG4bK / colliding branch ID -> SIP 400 / 482
  const viaChainOrBranchBlocked =
    evaluateSipRfc3261Rfc3581Rfc5626ViaHeaderChainAmplificationBranchCollisionAndFlowTokenHijackGuard({
      topmostViaSentByHostMatchesSourceIp: true,
      untrustedEndpointPrePopulatedReceivedOrRport: false,
      viaHeaderHopCount: 42,
      maxAllowedViaHeaderHops: 16,
      totalViaHeaderBlockBytes: 6800,
      maxAllowedViaHeaderBlockBytes: 4096,
      topmostViaBranchStartsWithZ9hG4bK: false,
      duplicateViaBranchWithMismatchedCseqMethodOrSentBy: true,
      rfc5626OutboundFlowTokenPresent: false,
      outboundFlowTokenHmacVerified: true,
      flowTokenBoundTlsTupleMatchesActiveConnection: true,
      recordRouteAttemptsTlsToUdpCleartextDowngrade: false,
    });
  assert.equal(viaChainOrBranchBlocked.allowed, false);
  assert.equal(viaChainOrBranchBlocked.viaChainAmplificationOrBranchCollisionDropped, true);
  assert.equal(
    viaChainOrBranchBlocked.actionCode,
    "REJECT_SIP_400_OR_482_ON_EXCESSIVE_VIA_CHAIN_OR_Z9HG4BK_BRANCH_COLLISION"
  );
  assert.equal(
    viaChainOrBranchBlocked.reason,
    "RFC3261_RFC5393_VIA_HEADER_CHAIN_AMPLIFICATION_OR_Z9HG4BK_BRANCH_TRANSACTION_COLLISION_BLOCKED"
  );

  // 3. RFC 5626 Outbound flow-token HMAC/tuple hijack or Record-Route TLS->UDP downgrade -> SIP 430 / 403
  const flowTokenHijackBlocked =
    evaluateSipRfc3261Rfc3581Rfc5626ViaHeaderChainAmplificationBranchCollisionAndFlowTokenHijackGuard({
      topmostViaSentByHostMatchesSourceIp: true,
      untrustedEndpointPrePopulatedReceivedOrRport: false,
      viaHeaderHopCount: 3,
      maxAllowedViaHeaderHops: 16,
      totalViaHeaderBlockBytes: 420,
      maxAllowedViaHeaderBlockBytes: 4096,
      topmostViaBranchStartsWithZ9hG4bK: true,
      duplicateViaBranchWithMismatchedCseqMethodOrSentBy: false,
      rfc5626OutboundFlowTokenPresent: true,
      outboundFlowTokenHmacVerified: false,
      flowTokenBoundTlsTupleMatchesActiveConnection: false,
      recordRouteAttemptsTlsToUdpCleartextDowngrade: true,
    });
  assert.equal(flowTokenHijackBlocked.allowed, false);
  assert.equal(flowTokenHijackBlocked.outboundFlowTokenOrTransportDowngradeBlocked, true);
  assert.equal(
    flowTokenHijackBlocked.actionCode,
    "REJECT_SIP_430_FLOW_FAILED_OR_403_ON_OUTBOUND_FLOW_TOKEN_TUPLE_HIJACK_OR_TLS_DOWNGRADE"
  );
  assert.equal(
    flowTokenHijackBlocked.reason,
    "RFC5626_OUTBOUND_FLOW_TOKEN_HMAC_TUPLE_MISMATCH_OR_RECORD_ROUTE_TLS_TO_UDP_DOWNGRADE_BLOCKED"
  );

  // 4. Compliant SIP Via chain and RFC 5626 Outbound flow routing
  const compliantSipViaRouting =
    evaluateSipRfc3261Rfc3581Rfc5626ViaHeaderChainAmplificationBranchCollisionAndFlowTokenHijackGuard({
      topmostViaSentByHostMatchesSourceIp: true,
      untrustedEndpointPrePopulatedReceivedOrRport: false,
      viaHeaderHopCount: 3,
      maxAllowedViaHeaderHops: 16,
      totalViaHeaderBlockBytes: 410,
      maxAllowedViaHeaderBlockBytes: 4096,
      topmostViaBranchStartsWithZ9hG4bK: true,
      duplicateViaBranchWithMismatchedCseqMethodOrSentBy: false,
      rfc5626OutboundFlowTokenPresent: true,
      outboundFlowTokenHmacVerified: true,
      flowTokenBoundTlsTupleMatchesActiveConnection: true,
      recordRouteAttemptsTlsToUdpCleartextDowngrade: false,
    });
  assert.equal(compliantSipViaRouting.allowed, true);
  assert.equal(
    compliantSipViaRouting.actionCode,
    "ALLOW_VERIFIED_SIP_VIA_AND_OUTBOUND_FLOW_ROUTING"
  );
  assert.equal(
    compliantSipViaRouting.reason,
    "SIP_RFC3261_RFC3581_RFC5626_VIA_CHAIN_RPORT_Z9HG4BK_AND_OUTBOUND_FLOW_VERIFIED"
  );
});

