  assert.equal(
    glareRetryStormBlocked.reason,
    "RFC3261_SECTION_14_1_REINVITE_GLARE_491_ZERO_BACKOFF_RETRY_STORM_BLOCKED"
  );

  // 2. Session-Expires downgraded to 10s (<90s Min-SE floor) -> reject 422 Session Interval Too Small with Min-SE: 90
