test("evaluateWebrtcRtpMixerRfc3550Rfc6465CsrcListOverflowIdentitySpoofAudioLevelDominantSpeakerHijackAndBridgeLoopbackGuard blocks CSRC header overflow, csrc-audio-level 0 dBov floor hijack, and cross-bridge loopback echo-bomb (P186)", () => {
  // 1. CSRC count (CC*4) header overshoot or self-SSRC loop in CSRC list -> drop malformed packet
  const csrcOverflowOrLoopDropped =
    evaluateWebrtcRtpMixerRfc3550Rfc6465CsrcListOverflowIdentitySpoofAudioLevelDominantSpeakerHijackAndBridgeLoopbackGuard({
      csrcCountHeaderOvershootOrSelfSsrcLoopDetected: true,
      csrcAudioLevelExtensionMismatchOrFakeFullScaleDominantSpeakerHijack: false,
      crossBridgeLoopbackEnergyCorrelation: 0.25,
      maxAllowedLoopbackCorrelation: 0.92,
      consecutiveLoopbackFramesDetected: 0,
    });
  assert.equal(csrcOverflowOrLoopDropped.allowed, false);
  assert.equal(csrcOverflowOrLoopDropped.csrcHeaderOverflowOrIdentityLoopDropped, true);
  assert.equal(
    csrcOverflowOrLoopDropped.policyCode,
    "P186-WEBRTC-RTP-MIXER-RFC3550-RFC6465-CSRC-LIST-OVERFLOW-IDENTITY-SPOOF-AUDIO-LEVEL-DOMINANT-SPEAKER-HIJACK-AND-BRIDGE-LOOPBACK-GUARD"
  );
  assert.equal(
    csrcOverflowOrLoopDropped.actionCode,
    "DROP_MALFORMED_CSRC_RTP_PACKET_AND_PRUNE_LOOPED_OR_SPOOFED_CSRC_IDENTIFIERS"
  );
  assert.equal(
    csrcOverflowOrLoopDropped.reason,
    "RFC3550_SECTION_5_1_CSRC_COUNT_BUFFER_OVERFLOW_OR_SELF_SSRC_MIXER_LOOP_DETECTED"
  );

  // 2. RFC 6465 csrc-audio-level extension count mismatch or silent PCM spoofing 0 dBov dominant-speaker hijack -> strip extension & recompute RMS floor
  const csrcAudioLevelHijackSanitized =
    evaluateWebrtcRtpMixerRfc3550Rfc6465CsrcListOverflowIdentitySpoofAudioLevelDominantSpeakerHijackAndBridgeLoopbackGuard({
      csrcCountHeaderOvershootOrSelfSsrcLoopDetected: false,
      csrcAudioLevelExtensionMismatchOrFakeFullScaleDominantSpeakerHijack: true,
      crossBridgeLoopbackEnergyCorrelation: 0.25,
      maxAllowedLoopbackCorrelation: 0.92,
      consecutiveLoopbackFramesDetected: 0,
    });
  assert.equal(csrcAudioLevelHijackSanitized.allowed, false);
  assert.equal(csrcAudioLevelHijackSanitized.csrcAudioLevelDominantSpeakerHijackSanitized, true);
  assert.equal(
    csrcAudioLevelHijackSanitized.actionCode,
    "STRIP_SPOOFED_RFC6465_CSRC_AUDIO_LEVEL_EXTENSION_AND_RECOMPUTE_PCM_RMS_FLOOR_CONTROL"
  );
  assert.equal(
    csrcAudioLevelHijackSanitized.reason,
    "RFC6465_CSRC_AUDIO_LEVEL_EXTENSION_COUNT_MISMATCH_OR_SILENT_0DBOV_FLOOR_HIJACK_BLOCKED"
  );

  // 3. Cross-bridge loopback correlation >= 0.92 for >= 3 consecutive frames -> mute loopback mixer port
  const crossBridgeLoopbackMuted =
    evaluateWebrtcRtpMixerRfc3550Rfc6465CsrcListOverflowIdentitySpoofAudioLevelDominantSpeakerHijackAndBridgeLoopbackGuard({
      csrcCountHeaderOvershootOrSelfSsrcLoopDetected: false,
      csrcAudioLevelExtensionMismatchOrFakeFullScaleDominantSpeakerHijack: false,
      crossBridgeLoopbackEnergyCorrelation: 0.97,
      maxAllowedLoopbackCorrelation: 0.92,
      consecutiveLoopbackFramesDetected: 5,
    });
  assert.equal(crossBridgeLoopbackMuted.allowed, false);
  assert.equal(crossBridgeLoopbackMuted.crossBridgeLoopbackEchoBombMuted, true);
  assert.equal(
    crossBridgeLoopbackMuted.actionCode,
    "MUTE_CROSS_BRIDGE_LOOPBACK_MIXER_PORT_AND_INSERT_CSRC_LOOP_SUPPRESSION_FILTER"
  );
  assert.equal(
    crossBridgeLoopbackMuted.reason,
    "RFC3550_SECTION_8_2_CROSS_BRIDGE_RTP_MIXER_LOOPBACK_ECHO_BOMB_DETECTED"
  );

  // 4. Compliant multi-party RTP mixer CSRC media frame
  const compliantMixerFrame =
    evaluateWebrtcRtpMixerRfc3550Rfc6465CsrcListOverflowIdentitySpoofAudioLevelDominantSpeakerHijackAndBridgeLoopbackGuard({
      csrcCountHeaderOvershootOrSelfSsrcLoopDetected: false,
      csrcAudioLevelExtensionMismatchOrFakeFullScaleDominantSpeakerHijack: false,
      crossBridgeLoopbackEnergyCorrelation: 0.25,
      maxAllowedLoopbackCorrelation: 0.92,
      consecutiveLoopbackFramesDetected: 0,
    });
  assert.equal(compliantMixerFrame.allowed, true);
  assert.equal(
    compliantMixerFrame.actionCode,
    "ALLOW_VERIFIED_MULTI_PARTY_RTP_MIXER_CSRC_MEDIA_FRAME"
  );
  assert.equal(
    compliantMixerFrame.reason,
    "WEBRTC_RTP_MIXER_RFC3550_RFC6465_CSRC_ROSTER_AUDIO_LEVEL_AND_BRIDGE_LOOP_VERIFIED"
  );
});

